n    // data\n    public maps;\n    public selectedMap;\n\n    // user\n    public user: User;\n\n    // network\n    public joinedRoom;\n\n    // PVP params from URL\n    public pvpRoom: string | null = null;\n    public pvpMatch: string | null = null;\n    public pvpMaxPlayers: number = 2;\n    public isPvpMode: boolean = false;\n\n    constructor(app) {\n        // core\n        this.engine = app.engine;\n        this.config = app.config;\n        this.scene = app.scene;\n\n        // Parse URL params for PVP mode\n        const params = new URLSearchParams(window.location.search);\n        this.pvpRoom = params.get(\"room\");\n        this.pvpMatch = params.get(\"match\");\n        this.pvpMaxPlayers = parseInt(params.get(\"players\") || \"2\", 10);\n        const nameParam = params.get(\"name\");\n        this.isPvpMode = !!this.pvpRoom;\n\n        // create user\n        this.user = {\n            displayName: nameParam || generateUserName(),\n        };\n\n        // create colyseus client\n        this.client = new Network(app.config.port);\n\n        // data\n        this.maps = maps;\n        this.selectedMap = maps.map_01; // default map\n\n        // If PVP mode, auto-join room\n        if (this.isPvpMode) {\n            this.autoJoinPvpRoom();\n        }\n    }\n\n    private async autoJoinPvpRoom() {\n        try {\n            const room = await this.client.createOrJoin(this.pvpRoom, {\n                displayName: this.user.displayName,\n                maxClient: this.pvpMaxPlayers,\n            });\n            this.joinedRoom = room;\n            // Skip to game scene directly (RoomScene handles the lobby)\n            this.setScene(SceneName.ROOM);\n        } catch (e) {\n            console.error(\"Failed to auto-join PVP room:\", e);\n        }\n    }\n\n    /////////////////////////////////////////\n    //////////// SCENE MANAGEMENT ///////////\n    /////////////////////////////////////////\n\n    public setScene(newState: SceneName) {\n        this.nextScene = newState;\n    }\n}\n","import { StandardMaterial } from \"@babylonjs/core/Materials/standardMaterial\";\nimport { Color3, Color4 } from \"@babylonjs/core/Maths/math.color\";\nimport { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { MeshBuilder } from \"@babylonjs/core/Meshes/meshBuilder\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { MapHelper } from \"../../../shared/MapHelper\";\nimport { Texture } from \"@babylonjs/core/Materials/Textures/texture\";\nimport { ShadowGenerator } from \"@babylonjs/core/Lights/Shadows/shadowGenerator\";\nimport { SceneLoader } from \"@babylonjs/core/Loading/sceneLoader\";\nimport { Mesh } from \"@babylonjs/core/Meshes/mesh\";\nimport { ParticleSystem } from \"@babylonjs/core/Particles/particleSystem\";\nimport { Sound } from \"@babylonjs/core/Audio/sound\";\n\nexport class LevelGenerator {\n    private _scene: Scene;\n    private _map: MapHelper;\n    private _shadow: ShadowGenerator;\n\n    public assets = [];\n    private materials = [];\n    private offset_x: number = 0;\n    private offset_z: number = 0;\n\n    public instances = [];\n    public bombModel;\n    public explosionTexture;\n\n    constructor(scene: Scene, map: MapHelper, shadow: ShadowGenerator) {\n        //\n        this._scene = scene;\n        this._map = map;\n        this._shadow = shadow;\n\n        // create materials first\n        this.generateMaterials();\n\n        // create models first\n        this.generateTiles();\n\n        // generate level\n        this.generateMeshes(this._map.mapData);\n    }\n\n    public async loadModels() {\n        let model = await SceneLoader.ImportMeshAsync(\"\", \"models/\", \"bomb_01.glb\");\n        this.bombModel = this.mergeMesh(\"bomb_01\", model.meshes[0]);\n        console.log(this.bombModel);\n    }\n\n    mergeMesh(key, mesh) {\n        // pick what you want to merge\n        const allChildMeshes = mesh.getChildTransformNodes(true)[0].getChildMeshes(false);\n\n        // multiMaterial = true\n        const merged = Mesh.MergeMeshes(allChildMeshes, false, true, undefined, undefined, true);\n        if (merged) {\n            merged.name = key + \"_MergedModel\";\n        }\n        return merged;\n    }\n\n    //\n    public generateMaterials() {\n        let wallTxt = new Texture(\"textures/wall_04.jpg\", this._scene);\n        let groundTxt = new Texture(\"textures/ground_03.jpg\", this._scene);\n        let wallBrokenTxt = new Texture(\"textures/wall_03.jpg\", this._scene);\n        let blastTxt = new Texture(\"textures/blast.png\", this._scene);\n\n        for (let tileID in this._map.tiles) {\n            let tile = this._map.tiles[tileID];\n\n            // ground or spawnpoint\n            if (tile.id === \" \" || tile.id === \"S\") {\n                const material = new StandardMaterial(\"material-ground\", this._scene);\n                material.diffuseTexture = groundTxt;\n                material.specularColor = Color3.Black();\n                this.materials[tile.name] = material;\n            }\n\n            // wall\n            if (tile.id === \"W\") {\n                const material = new StandardMaterial(\"material-wall\", this._scene);\n                material.diffuseTexture = wallTxt;\n                material.specularColor = Color3.Black();\n                this.materials[tile.name] = material;\n            }\n\n            // broken wall\n            if (tile.id === \"B\") {\n                const material = new StandardMaterial(\"material-broken\", this._scene);\n                material.diffuseTexture = wallBrokenTxt;\n                material.specularColor = Color3.Black();\n                this.materials[tile.name] = material;\n            }\n\n            // bomb\n            if (tile.id === \"T\") {\n                const material = new StandardMaterial(\"material-bomb\", this._scene);\n                material.diffuseColor = Color3.Black();\n                material.specularColor = Color3.Black();\n                this.materials[tile.name] = material;\n            }\n\n            // explosion\n            if (tile.id === \"E\") {\n                const material = new StandardMaterial(\"material-explosion\", this._scene);\n                material.diffuseColor = Color3.FromHexString(\"#bd521c\");\n                material.specularColor = Color3.Black();\n                //material.disableLighting = true;\n                this.materials[tile.name] = material;\n            }\n        }\n    }\n\n    public generateTiles() {\n        for (let tileID in this._map.tiles) {\n            let tile = this._map.tiles[tileID];\n\n            // ground or spawnpoint\n            if (tile.id === \" \" || tile.id === \"S\") {\n                const box = MeshBuilder.CreateBox(\"box-\" + tile.name, { size: tile.width, height: 0.1 }, this._scene);\n                box.position = new Vector3(0, 0, 0);\n                box.material = this.materials[tile.name];\n                box.receiveShadows = true;\n                box.isVisible = false;\n                this.assets[tile.name] = box;\n            }\n\n            // wall\n            if (tile.id === \"W\") {\n                const box = MeshBuilder.CreateBox(\"box-\" + tile.name, { size: tile.width, height: 2 }, this._scene);\n                box.position = new Vector3(0, 0, 0);\n                box.material = this.materials[tile.name];\n                box.isVisible = false;\n                this.assets[tile.name] = box;\n            }\n\n            // broken wall\n            if (tile.id === \"B\") {\n                const box = MeshBuilder.CreateBox(\"box-\" + tile.name, { size: tile.width, height: 2 }, this._scene);\n                box.position = new Vector3(0, 0, 0);\n                box.material = this.materials[tile.name];\n                box.isVisible = false;\n                this.assets[tile.name] = box;\n            }\n\n            // bomb\n            if (tile.id === \"T\") {\n                const box = MeshBuilder.CreateBox(\"box-\" + tile.name, { size: 1, height: 1 }, this._scene);\n                box.position = new Vector3(0, 0.5, 0);\n                box.material = this.materials[tile.name];\n                box.isVisible = false;\n                this.assets[tile.name] = box;\n            }\n\n            // explosion\n            if (tile.id === \"E\") {\n                const box = MeshBuilder.CreateSphere(\"box-\" + tile.name, { diameter: 1 }, this._scene);\n                box.position = new Vector3(0, 0.5, 0);\n                box.material = this.materials[tile.name];\n                box.isVisible = false;\n                box.visibility = 0;\n                this.assets[tile.name] = box;\n            }\n        }\n\n        //\n        const box = MeshBuilder.CreateSphere(\"powerup\", { diameter: 0.5 }, this._scene);\n        box.position = new Vector3(0, 0.5, 0);\n        box.isEnabled(false);\n        this.assets[\"powerup\"] = box;\n\n        var material = new StandardMaterial(\"powerup_0\");\n        material.diffuseColor = Color3.Blue();\n\n        var material = new StandardMaterial(\"powerup_1\");\n        material.diffuseColor = Color3.Red();\n\n        var material = new StandardMaterial(\"powerup_2\");\n        material.diffuseColor = Color3.Yellow();\n\n        // particule\n        this.explosionTexture = this._scene.getTextureByName(\"textures/particle_01.png\");\n        if (!this.explosionTexture) {\n            this.explosionTexture = new Texture(\"textures/particle_01.png\", this._scene);\n        }\n\n        var particleSystem = new ParticleSystem(\"particles\", 1000, this._scene);\n        particleSystem.particleTexture = this.explosionTexture;\n        particleSystem.emitter = this.assets[\"explosion\"]; // the starting location\n        // Colors of all particles\n        particleSystem.color1 = Color4.FromHexString(\"#f58d42\");\n        particleSystem.color2 = Color4.FromHexString(\"#ff1900\");\n        particleSystem.colorDead = new Color4(0, 0, 0, 1);\n        // Size of each particle (random between...\n        particleSystem.minSize = 0.2;\n        particleSystem.maxSize = 0.4;\n        // Life time of each particle (random between...\n        particleSystem.minLifeTime = 0.2;\n        particleSystem.maxLifeTime = 1.5;\n        particleSystem.targetStopDuration = 1.5;\n        // Emission rate\n        particleSystem.emitRate = 1000;\n        particleSystem.createSphereEmitter(0.1);\n        particleSystem.updateSpeed = 0.09;\n        this.assets[\"particleSystem\"] = particleSystem;\n\n        // LOAD SOUNDS\n        let explosionSound = new Sound(\n            \"explosionSound\",\n            \"./sounds/explosion.mp3\",\n            this._scene,\n            () => {\n                this.assets[\"explosionSound\"] = explosionSound;\n                console.log(\"SOUND LOADED\", this.assets);\n            },\n            {\n                loop: false,\n                autoplay: false,\n                volume: 0.1,\n            }\n        );\n    }\n\n    public async generateMeshes(map: string) {\n        this._map.mapData.forEach((col, colId) => {\n            col.forEach((tileID, rowId) => {\n                //this.createInstance(tileID, colId, rowId);\n            });\n        });\n    }\n\n    createInstance(tileID, colId, rowId) {\n        let tile = this._map.findTile(tileID);\n        if (tile) {\n            let posX = rowId - this.offset_x;\n            let posZ = colId - this.offset_z;\n            let offset_y = tile.offset_y ?? 0;\n            // ground\n            if (tile.id === \" \" || tile.id === \"S\") {\n                let instance = this.assets[tile.name].createInstance(\"box-\" + rowId + \"-\" + colId);\n                instance.position = new Vector3(posX, offset_y, posZ);\n                instance.metadata = tile;\n                instance.receiveShadows = true;\n                instance.freezeWorldMatrix();\n                this.instances.push(instance);\n            }\n\n            // wall\n            if (tile.id === \"W\") {\n                let instance = this.assets[tile.name].createInstance(\"box-\" + rowId + \"-\" + colId);\n                instance.position = new Vector3(posX, offset_y, posZ);\n                instance.metadata = tile;\n                instance.freezeWorldMatrix();\n                this._shadow.addShadowCaster(instance, true);\n                this.instances.push(instance);\n            }\n        }\n    }\n}\n","// colyseus\nimport { Client, Room } from \"colyseus.js\";\nimport { isLocal } from \"../Utils/Utils\";\n\nexport class Network {\n    public _client: Client;\n\n    constructor(port) {\n        // create colyseus client - connect to bomberman server\n        let url: string;\n        if (isLocal()) {\n            url = \"ws://localhost:\" + port;\n        } else {\n            // Production: connect via bomberman relay\n            const proto = window.location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n            url = proto + \"//"+window.location.hostname+"/ws/bomberman\";\n        }\n        this._client = new Client(url);\n    }\n\n    public async joinLobby(): Promise<any> {\n        return new Promise(async (resolve: any, reject: any) => {\n            return await this._client\n                .joinOrCreate(\"lobby\")\n                .then((lobbyJoined) => {\n                    resolve(lobbyJoined);\n                })\n                .catch((e: any) => {\n                    console.error(\"JOIN ERROR\", e);\n                    reject(e);\n                });\n        });\n    }\n\n    public async create(displayName: string = \"test\"): Promise<any> {\n        return new Promise(async (resolve: any, reject: any) => {\n            let options = {\n                name: displayName,\n                map: \"map_01\",\n                maxClient: 4,\n            };\n            this._client\n                .create(\"gameroom\", options)\n                .then((joinedRoom: Room) => {\n                    resolve(joinedRoom);\n                })\n                .catch((e: any) => {\n                    console.error(\"JOIN ERROR\", e);\n                    reject(e);\n                });\n        });\n    }\n\n    public async join(roomId, displayName: string = \"test\"): Promise<any> {\n        return new Promise(async (resolve: any, reject: any) => {\n            let options = {\n                name: displayName,\n            };\n            this._client\n                .joinById(roomId, options)\n                .then((joinedRoom: Room) => {\n                    resolve(joinedRoom);\n                })\n                .catch((e: any) => {\n                    console.error(\"JOIN ERROR\", e);\n                    reject(e);\n                });\n        });\n    }\n\n    public async createOrJoin(roomId, user): Promise<any> {\n        return new Promise(async (resolve: any, reject: any) => {\n            this._client.getAvailableRooms(\"gameroom\").then((rooms) => {\n                let foundRoom;\n                rooms.forEach((room) => {\n                    if (room.roomId === roomId) {\n                        foundRoom = room;\n                    }\n                });\n                if (foundRoom) {\n                    this._client\n                        .joinById(foundRoom.roomId, user)\n                        .then((joinedRoom: Room) => {\n                            console.info(\"JOIN SUCCESS\", joinedRoom);\n                            resolve(joinedRoom);\n                        })\n                        .catch((e: any) => {\n                            console.error(\"JOIN ERROR\", e);\n                            reject(e);\n                        });\n                } else {\n                    this._client\n                        .create(\"gameroom\", {\n                            roomId: roomId,\n                            name: user.displayName,\n                            map: \"map_01\",\n                            maxClient: user.maxClient || 4,\n                        })\n                        .then((joinedRoom: Room) => {\n                            console.info(\"CREATE SUCCESS\", joinedRoom);\n                            resolve(joinedRoom);\n                        })\n                        .catch((e: any) => {\n                            console.error(\"CREATE ERROR\", e);\n                        });\n                }\n            });\n        });\n    }\n\n    /*\n    public async joinRoom(roomId, token, character_id): Promise<any> {\n        return await this._client.joinById(roomId, {\n            token: token,\n            character_id: character_id,\n        });\n    }\n\n    public async joinChatRoom(data): Promise<any> {\n        return await this._client.joinOrCreate(\"chat_room\", data);\n    }\n\n    public async findCurrentRoom(currentRoomKey): Promise<any> {\n        return new Promise(async (resolve: any, reject: any) => {\n            let rooms = await this._client.getAvailableRooms(\"game_room\");\n            if (rooms.length > 0) {\n                rooms.forEach((room) => {\n                    if (room.metadata.location === currentRoomKey) {\n                        resolve(room);\n                    }\n                });\n            }\n            resolve(false);\n        });\n    }\n\n    public async joinOrCreateRoom(location, token, character_id): Promise<any> {\n        // find all exisiting rooms\n        let rooms = await this._client.getAvailableRooms(\"game_room\");\n\n        // rooms exists\n        if (rooms.length > 0) {\n            // do we already have a room for the specified location\n            let roomIdFound: boolean | string = false;\n            rooms.forEach((room) => {\n                if (room.metadata.location === location) {\n                    roomIdFound = room.roomId;\n                }\n            });\n\n            // if so, let's join it\n            if (roomIdFound !== false) {\n                return await this.joinRoom(roomIdFound, token, character_id);\n            }\n        }\n\n        // else create a new room for that location\n        return await this._client.create(\"game_room\", {\n            location: location,\n            token: token,\n            character_id: character_id,\n        });\n    }*/\n}\n","import { Scene } from \"@babylonjs/core/scene\";\nimport { UniversalCamera } from \"@babylonjs/core/Cameras/universalCamera\";\nimport { TransformNode } from \"@babylonjs/core/Meshes/transformNode\";\nimport { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\n\nexport class PlayerCamera {\n    private _scene: Scene;\n    private _cameraRoot;\n    public camera: UniversalCamera;\n\n    public shakeTimer;\n    public shouldShake: boolean = false;\n\n    constructor(scene) {\n        this._scene = scene;\n\n        //set up camera\n        var cameraRoot = new TransformNode(\"cameraRoot\");\n        cameraRoot.position = new Vector3(0, 1.5, 0);\n        cameraRoot.rotation = new Vector3(0, 0, 0);\n        this._cameraRoot = cameraRoot;\n\n        var camYAxis = new TransformNode(\"camYAxis\");\n        camYAxis.rotation = new Vector3(1.2, 0, 0);\n        camYAxis.parent = cameraRoot;\n\n        var camera = new UniversalCamera(\"playercamera\", new Vector3(0, 1, -45), this._scene);\n        camera.lockedTarget = cameraRoot.position;\n        camera.fov = 0.35;\n        camera.parent = camYAxis;\n\n        this.camera = camera;\n    }\n\n    shake() {\n        this.shouldShake = true;\n        var projectionMatrix = this.camera.getProjectionMatrix();\n        var r = projectionMatrix.getRow(3);\n        var t = 0;\n        this._scene.registerBeforeRender(() => {\n            if (this.shouldShake === true) {\n                r.x += Math.cos(t) * 0.3;\n                r.y += Math.sin(t) * 0.3;\n                projectionMatrix.setRowFromFloats(3, r.x, r.y, r.z, r.w);\n                t += 81337.18;\n            }\n        });\n\n        this.shakeTimer = setTimeout(() => {\n            this.shouldShake = false;\n        }, 300);\n    }\n\n    tween(player) {\n        //this._cameraRoot.position = player.position;\n        this._cameraRoot.position = Vector3.Lerp(this._cameraRoot.position, new Vector3(player.position.x, player.position.y, player.position.z), 0.2);\n    }\n}\n","import { Scene } from \"@babylonjs/core/scene\";\nimport { AdvancedDynamicTexture } from \"@babylonjs/gui/2D/advancedDynamicTexture\";\nimport { DebugBox } from \"./UI/DebugBox\";\nimport { Engine } from \"@babylonjs/core/Engines/engine\";\nimport { Rectangle } from \"@babylonjs/gui/2D/controls/rectangle\";\nimport { TextBlock, TextWrapping } from \"@babylonjs/gui/2D/controls/textBlock\";\nimport { Button } from \"@babylonjs/gui/2D/controls/button\";\nimport { Control } from \"@babylonjs/gui/2D/controls/control\";\nimport { SceneName, ServerMsg } from \"../../../shared/types\";\nimport { GameScene } from \"../Scenes/GameScene\";\nimport { CharacterStats } from \"./UI/CharacterStats\";\nimport { ScoreBoard } from \"./UI/ScoreBoard\";\n\nexport class PlayerUI {\n    public _scene: Scene;\n    private _engine: Engine;\n    public _game;\n    public _entities;\n    private _room;\n    public _currentPlayer;\n\n    public _ui: AdvancedDynamicTexture;\n    public _uiLabels: AdvancedDynamicTexture;\n\n    public _DebugBox: DebugBox;\n    public _CharacterStats: CharacterStats;\n    public _ScoreBoard: ScoreBoard;\n\n    constructor(scene, engine, gameScene: GameScene) {\n        this._scene = scene;\n        this._engine = engine;\n        this._game = gameScene._game;\n        this._entities = gameScene.entities;\n        this._room = gameScene._game.joinedRoom;\n\n        // create ui\n        this._uiLabels = AdvancedDynamicTexture.CreateFullscreenUI(\"UI_Names\", true, this._scene);\n\n        // create adt\n        this._ui = AdvancedDynamicTexture.CreateFullscreenUI(\"UI_Player\", true, this._scene);\n\n        // create base ui\n        this.create(gameScene);\n\n        // setup ui events\n        this._room.onMessage(ServerMsg.PONG, (message) => {\n            console.log(ServerMsg[ServerMsg.START_GAME], message);\n        });\n    }\n\n    setCurrentPlayer(entity) {\n        // create debug ui + events\n        //this._DebugBox = new DebugBox(this._ui, this._engine, this._scene, entity, this._room);\n\n        //\n        this._CharacterStats = new CharacterStats(this._ui, this._engine, this._scene, entity, this._game);\n        this._ScoreBoard = new ScoreBoard(this, entity);\n\n        // debug\n        /*\n        setTimeout(() => {\n            this._entities.forEach((element) => {\n                if (element.type !== \"player\") {\n                    this.createDebugCells(element);\n                }\n            });\n        }, 500);*/\n    }\n\n    create(gameScene) {\n        const cancelButton = Button.CreateSimpleButton(\"cancelButton\", \"QUIT\");\n        cancelButton.fontFamily = this._game.config.fontFamily;\n        cancelButton.widthInPixels = 100;\n        cancelButton.topInPixels = 15;\n        cancelButton.leftInPixels = -15;\n        cancelButton.height = \"30px\";\n        cancelButton.color = this._game.config.primary_color;\n        cancelButton.background = \"white\";\n        cancelButton.thickness = 1;\n        cancelButton.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_RIGHT;\n        cancelButton.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        this._ui.addControl(cancelButton);\n\n        cancelButton.onPointerUpObservable.add(() => {\n            window.location.hash = \"\";\n            gameScene.room.leave();\n            gameScene._game.setScene(SceneName.HOME);\n        });\n\n        // Hide QUIT button in PVP mode — game ends via elimination only\n        if (this._game.isPvpMode) {\n            cancelButton.isVisible = false;\n        }\n    }\n\n    public createDebugCells(entity) {\n        let title = entity.id;\n        var rect1 = new Rectangle(\"item_nameplate_\" + entity.sessionId);\n        rect1.isVisible = true;\n        rect1.width = \"100px\";\n        rect1.height = \"40px\";\n        rect1.alpha = 1;\n        rect1.thickness = 0;\n        this._uiLabels.addControl(rect1);\n        rect1.linkWithMesh(entity);\n        rect1.linkOffsetY = -10;\n\n        var label = new TextBlock(\"item_nameplate_text_\" + entity.sessionId);\n        label.fontFamily = \"Arial\";\n        label.text = title;\n        label.color = \"black\";\n        label.fontWeight = \"bold\";\n        label.fontSize = \"10px\";\n        label.textWrapping = TextWrapping.WordWrap;\n        rect1.addControl(label);\n        return rect1;\n    }\n\n    public createEntityLabel(entity) {\n        let title = entity.name !== \"\" ? entity.name : entity.id;\n        console.log(title);\n        var rect1 = new Rectangle(\"item_nameplate_\" + entity.sessionId);\n        rect1.isVisible = true;\n        rect1.width = \"100px\";\n        rect1.height = \"40px\";\n        rect1.thickness = 0;\n        this._uiLabels.addControl(rect1);\n        rect1.linkWithMesh(entity);\n        rect1.linkOffsetY = -10;\n\n        var label = new TextBlock(\"item_nameplate_text_\" + entity.sessionId);\n        label.fontFamily = this._game.config.fontFamily;\n        label.text = title;\n        label.color = this._game.config.secondary_color;\n        label.fontWeight = \"bold\";\n        label.fontSize = \"16px\";\n        label.textWrapping = TextWrapping.WordWrap;\n        label.outlineWidth = 3;\n        label.outlineColor = this._game.config.primary_color;\n        rect1.addControl(label);\n        return rect1;\n    }\n}\n","import { Engine } from \"@babylonjs/core/Engines/engine\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { AdvancedDynamicTexture, TextBlock, Rectangle, Control } from \"@babylonjs/gui/2D\";\nimport { countPlayers, roundTo } from \"../../Utils/Utils\";\nimport { Entity } from \"../../Entities/Entity\";\nimport { GameController } from \"../GameController\";\n\nexport class CharacterStats {\n    private _engine: Engine;\n    private _scene: Scene;\n    private ping: number = 0;\n    private _entity: Entity;\n    private _game: GameController;\n\n    private _ui;\n    private _debugTextUI;\n\n    constructor(ui: AdvancedDynamicTexture, engine: Engine, scene: Scene, entity: Entity, game: GameController) {\n        this._ui = ui;\n        this._engine = engine;\n        this._scene = scene;\n        this._entity = entity;\n        this._game = game;\n\n        this._createUI();\n\n        // some ui must be constantly refreshed as things change\n        this._scene.registerBeforeRender(() => {\n            // refresh\n            this._update();\n        });\n    }\n\n    _createUI() {\n        let debugPanel = new Rectangle(\"panel-debugBox\");\n        debugPanel.thickness = 0;\n        debugPanel.top = \"-15px\";\n        debugPanel.fontFamily = this._game.config.fontFamily;\n        debugPanel.left = \"15px\";\n        debugPanel.width = 1;\n        debugPanel.height = \"200px;\";\n        debugPanel.background = \"rgba(0,0,0,0)\";\n        debugPanel.verticalAlignment = Control.VERTICAL_ALIGNMENT_BOTTOM;\n        debugPanel.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        this._ui.addControl(debugPanel);\n\n        const debugText = new TextBlock(\"debugText\", \"\");\n        debugText.color = \"#FFF\";\n        debugText.top = \"5px\";\n        debugText.left = \"5px\";\n        debugText.fontSize = \"24px;\";\n        debugText.color = this._game.config.secondary_color;\n        debugText.outlineWidth = 10;\n        debugText.outlineColor = this._game.config.primary_color;\n        debugText.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        debugText.textVerticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        debugPanel.addControl(debugText);\n\n        this._debugTextUI = debugText;\n    }\n\n    // debug panel refresh\n    private _update() {\n        let locationText = \"\";\n        locationText += \"Health: \" + this._entity.health + \" \\n \";\n        locationText += \"Bombs: \" + this._entity.bombs + \" \\n \";\n        locationText += \"Speed: \" + this._entity.speed + \" \\n \";\n        this._debugTextUI.text = locationText;\n    }\n}\n","import { Engine } from \"@babylonjs/core/Engines/engine\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { Entity } from \"../../Entities/Entity\";\nimport { GameController } from \"../GameController\";\nimport { PlayerUI } from \"../PlayerUI\";\nimport { Control } from \"@babylonjs/gui/2D/controls/control\";\nimport { Rectangle } from \"@babylonjs/gui/2D/controls/rectangle\";\nimport { TextBlock } from \"@babylonjs/gui/2D/controls/textBlock\";\nimport { Color3 } from \"@babylonjs/core\";\n\nexport class ScoreBoard {\n    private _engine: Engine;\n    private _scene: Scene;\n    private ping: number = 0;\n    private _entity: Entity;\n    private _game: GameController;\n    private _entities;\n\n    private _ui;\n    private _panel;\n\n    constructor(playerUI: PlayerUI, entity) {\n        this._ui = playerUI._ui;\n        this._entities = playerUI._entities;\n        this._scene = playerUI._scene;\n        this._game = playerUI._game;\n\n        this._createUI();\n\n        // some ui must be constantly refreshed as things change\n        this._scene.registerBeforeRender(() => {\n            // refresh\n            this._update();\n        });\n    }\n\n    _createUI() {\n        let debugPanel = new Rectangle(\"panel-debugBox\");\n        debugPanel.thickness = 0;\n        debugPanel.top = \"15px\";\n        debugPanel.fontFamily = this._game.config.fontFamily;\n        debugPanel.left = \"15px\";\n        debugPanel.width = \"300px;\";\n        debugPanel.height = \"100px;\";\n        debugPanel.adaptHeightToChildren = false;\n        debugPanel.background = \"rgba(0,0,0, .5)\";\n        debugPanel.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        debugPanel.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        this._ui.addControl(debugPanel);\n        this._panel = debugPanel;\n    }\n\n    // debug panel refresh\n    private _update() {\n        // if already exists\n        this._panel.children.forEach((el) => {\n            el.dispose();\n        });\n\n        let top = 0;\n        this._entities.forEach((entity) => {\n            if (entity.type === \"player\") {\n                const debugText = new TextBlock(\"debugText\", entity.name + \": \" + entity.score);\n                debugText.color = \"#FFF\";\n                debugText.topInPixels = top;\n                debugText.left = \"5px\";\n                debugText.fontSize = \"22px;\";\n                debugText.height = \"25px\";\n                debugText.color = entity.color;\n                debugText.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n                debugText.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                debugText.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                debugText.textVerticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n                this._panel.addControl(debugText);\n\n                top = top + 25;\n            }\n        });\n    }\n}\n","import { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { PlayerInput } from \"./Entity/PlayerInput\";\nimport { PlayerCamera } from \"../Controllers/PlayerCamera\";\nimport { PlayerUI } from \"../Controllers/PlayerUI\";\nimport { Engine } from \"@babylonjs/core/Engines/engine\";\nimport { Animation } from \"@babylonjs/core/Animations/animation\";\nimport { GameScene } from \"../Scenes/GameScene\";\nimport { TransformNode } from \"@babylonjs/core/Meshes/transformNode\";\nimport { Mesh } from \"@babylonjs/core/Meshes/mesh\";\nimport { MapHelper } from \"../../../shared/MapHelper\";\nimport { LevelGenerator } from \"../Controllers/LevelGenerator\";\nimport { Explosion } from \"./Explosion\";\nimport { BounceEase, CircleEase, CubicEase, EasingFunction } from \"@babylonjs/core/Animations/easing\";\n\nexport class Bomb extends TransformNode {\n    public _camera: PlayerCamera;\n    public _engine: Engine;\n    public _map: MapHelper;\n    public _input: PlayerInput;\n    public _generator: LevelGenerator;\n    public _game;\n    public _entity;\n    public _room;\n    public _shadow;\n    public _ui: PlayerUI;\n    public playerMesh: Mesh;\n    public isCurrentPlayer;\n    public tile;\n\n    public sessionId: string = \"\";\n    public type: string = \"\";\n    public name: string = \"\";\n    public col: number = 0;\n    public row: number = 0;\n    public size: number = 1;\n\n    public nextScale: number;\n\n    constructor(name: string, scene: Scene, gameScene: GameScene, entity, isCurrentPlayer = false) {\n        super(name, scene);\n\n        // set variables\n        this._scene = scene;\n        this._engine = gameScene._engine;\n        this._map = gameScene._map;\n        this._room = gameScene.room;\n        this._game = gameScene._game;\n        this._generator = gameScene._generator;\n        this._ui = gameScene._ui;\n        this._shadow = gameScene._shadow;\n        this._entity = entity;\n        this.isCurrentPlayer = isCurrentPlayer;\n\n        // set entity\n        Object.assign(this, entity);\n\n        // set tile\n        this.tile = this._map.findTile(this.type, \"name\");\n\n        // set position\n        this.setPosition();\n\n        // spawn\n        this.spawn();\n\n        // update from server\n        this._entity.onChange(() => {\n            // update player data from server data\n            Object.assign(this, this._entity);\n\n            // set position\n            this.setPosition();\n        });\n    }\n\n    public spawn() {\n        let sizeMin = 0.6;\n        let sizeMax = 1;\n\n        // create mesh\n        let mesh = this._generator.bombModel;\n        let instance = mesh.createInstance(\"bomb-\" + this.col + \"-\" + this.row);\n        instance.scale = new Vector3(sizeMin, sizeMin, sizeMin);\n        instance.position = new Vector3(0, 0, 0);\n        instance.receiveShadows = true;\n        instance.parent = this;\n        instance.freezeWorldMatrix();\n        this.playerMesh = instance;\n\n        // add shadow\n        this._shadow.addShadowCaster(instance);\n\n        // Creating an easing function\n        const easingFunction = new CubicEase();\n        // For each easing function, you can choose between EASEIN (default), EASEOUT, EASEINOUT\n        easingFunction.setEasingMode(EasingFunction.EASINGMODE_EASEINOUT);\n\n        //Animate the bomb\n        const animWheel = new Animation(\"wheelAnimation\", \"scaling\", 30, Animation.ANIMATIONTYPE_VECTOR3, Animation.ANIMATIONLOOPMODE_CYCLE);\n\n        const wheelKeys = [];\n\n        //At the animation key 0, the value of rotation.y is 0\n        wheelKeys.push({\n            frame: 0,\n            value: new Vector3(sizeMin, sizeMin, sizeMin),\n        });\n\n        //At the animation key 30, (after 1 sec since animation fps = 30) the value of rotation.y is 2PI for a complete rotation\n        wheelKeys.push({\n            frame: 15,\n            value: new Vector3(sizeMax, sizeMax, sizeMax),\n        });\n\n        //At the animation key 60\n        wheelKeys.push({\n            frame: 30,\n            value: new Vector3(sizeMin, sizeMin, sizeMin),\n        });\n\n        //set the keys\n        animWheel.setKeys(wheelKeys);\n        animWheel.setEasingFunction(easingFunction);\n\n        //Link this animation to a bomb\n        instance.animations = [];\n        instance.animations.push(animWheel);\n\n        this._scene.beginAnimation(instance, 0, 60, true);\n    }\n\n    public setPosition() {\n        this.position = new Vector3(this.col, 0, this.row);\n    }\n\n    public update(delta: number) {}\n\n    public updateServerRate() {}\n\n    public delete() {\n        this.playerMesh.dispose();\n    }\n}\n","import { StandardMaterial } from \"@babylonjs/core/Materials/standardMaterial\";\nimport { Color3 } from \"@babylonjs/core/Maths/math.color\";\nimport { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { MeshBuilder } from \"@babylonjs/core/Meshes/meshBuilder\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { PlayerInput } from \"./Entity/PlayerInput\";\nimport { PlayerCamera } from \"../Controllers/PlayerCamera\";\nimport { PlayerUI } from \"../Controllers/PlayerUI\";\nimport { Engine } from \"@babylonjs/core/Engines/engine\";\nimport { GameScene } from \"../Scenes/GameScene\";\nimport { TransformNode } from \"@babylonjs/core/Meshes/transformNode\";\nimport { Mesh } from \"@babylonjs/core/Meshes/mesh\";\nimport { MapHelper } from \"../../../shared/MapHelper\";\nimport { LevelGenerator } from \"../Controllers/LevelGenerator\";\nimport tiles from \"../../../shared/Data/tiles.json\";\n\nexport class Cell extends TransformNode {\n    public _camera: PlayerCamera;\n    public _engine: Engine;\n    public _map: MapHelper;\n    public _input: PlayerInput;\n    public _generator: LevelGenerator;\n    public _game;\n    public _entity;\n    public _room;\n    public _shadow;\n    public _ui: PlayerUI;\n    public playerMesh: Mesh;\n    public isCurrentPlayer;\n    public tile;\n\n    public sessionId: string = \"\";\n    public type: string = \"\";\n    public name: string = \"\";\n    public col: number = 0;\n    public row: number = 0;\n\n    constructor(name: string, scene: Scene, gameScene: GameScene, entity, isCurrentPlayer = false) {\n        super(name, scene);\n\n        // set variables\n        this._scene = scene;\n        this._engine = gameScene._engine;\n        this._map = gameScene._map;\n        this._room = gameScene.room;\n        this._game = gameScene._game;\n        this._generator = gameScene._generator;\n        this._ui = gameScene._ui;\n        this._shadow = gameScene._shadow;\n        this._entity = entity;\n        this.isCurrentPlayer = isCurrentPlayer;\n\n        // set entity\n        Object.assign(this, entity);\n\n        this.name = this.id;\n\n        // set tile\n        this.tile = this._map.findTile(this.type, \"name\");\n\n        // set position\n        this.setPosition();\n\n        // spawn\n        this.spawn();\n\n        // update from server\n        this._entity.onChange(() => {\n            // update player data from server data\n            Object.assign(this, this._entity);\n\n            // set position\n            this.setPosition();\n        });\n    }\n\n    public spawn() {\n        // create instance\n        let instance = this._generator.assets[this.type].createInstance(\"box-\" + this.col + \"-\" + this.row);\n        instance.position = new Vector3(0, 0, 0);\n        instance.receiveShadows = true;\n        instance.parent = this;\n        instance.freezeWorldMatrix();\n        this.playerMesh = instance;\n\n        // add player shadow\n        this._shadow.addShadowCaster(instance);\n    }\n\n    public setPosition() {\n        this.position = new Vector3(this.col, 0, this.row);\n    }\n\n    public update(delta: number) {}\n\n    public updateServerRate() {}\n\n    public delete() {\n        this.playerMesh.dispose();\n    }\n}\n","import { StandardMaterial } from \"@babylonjs/core/Materials/standardMaterial\";\nimport { Color3 } from \"@babylonjs/core/Maths/math.color\";\nimport { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { MeshBuilder } from \"@babylonjs/core/Meshes/meshBuilder\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { PlayerInput } from \"./Entity/PlayerInput\";\nimport { PlayerCamera } from \"../Controllers/PlayerCamera\";\nimport { PlayerUI } from \"../Controllers/PlayerUI\";\nimport { Engine } from \"@babylonjs/core/Engines/engine\";\nimport { GameScene } from \"../Scenes/GameScene\";\nimport { TransformNode } from \"@babylonjs/core/Meshes/transformNode\";\nimport { Mesh } from \"@babylonjs/core/Meshes/mesh\";\nimport { MoveController } from \"./Entity/MoveController\";\nimport { MapHelper } from \"../../../shared/MapHelper\";\nimport { ServerMsg } from \"../../../shared/types\";\nimport { AxesViewer } from \"@babylonjs/core/Debug/axesViewer\";\n\nexport class Entity extends TransformNode {\n    public _camera: PlayerCamera;\n    public _engine: Engine;\n    public _map: MapHelper;\n    public _input: PlayerInput;\n    public _game;\n    public _entity;\n    public _room;\n    public _shadow;\n    public _ui: PlayerUI;\n    public playerMesh: Mesh;\n    public isCurrentPlayer;\n    public tile;\n    public characterLabel;\n    public moveController: MoveController;\n    public _entities;\n\n    public sessionId: string = \"\";\n    public type;\n    public name: string = \"\";\n    public col: number = 0;\n    public row: number = 0;\n    public bombs: number = 0;\n    public health: number = 0;\n    public color: string = \"#000000\";\n    public speed: number = 1;\n\n    constructor(name: string, scene: Scene, gameScene: GameScene, entity, isCurrentPlayer = false) {\n        super(name, scene);\n\n        // set variables\n        this._scene = scene;\n        this._engine = gameScene._engine;\n        this._map = gameScene._map;\n        this._room = gameScene.room;\n        this._game = gameScene._game;\n        this._ui = gameScene._ui;\n        this._shadow = gameScene._shadow;\n        this._entities = gameScene.entities;\n        this._entity = entity;\n        this.isCurrentPlayer = isCurrentPlayer;\n\n        // set entity\n        Object.assign(this, entity);\n\n        // set tile\n        this.tile = this._map.findTile(this.type, \"name\");\n\n        // spawn player\n        this.spawn();\n\n        // move controller\n        this.moveController = new MoveController(this);\n\n        // if current player\n        if (isCurrentPlayer) {\n            // set inputs\n            this._input = new PlayerInput(this);\n            this._camera = gameScene._camera;\n        }\n\n        // set default position\n        this.moveController.setPositionAndRotation(entity); // set next default position from server entity\n\n        // update from server\n        this._entity.onChange(() => {\n            // update player data from server data\n            Object.assign(this, this._entity);\n\n            // update entity position\n            if (!this.moveController.isAnimating && (this.row !== this.position.x || this.col !== this.position.z) && !this.isCurrentPlayer) {\n                let vertical = this.position.z - this.row;\n                let horizontal = this.position.x - this.col;\n                this.moveController.move(vertical, horizontal);\n            }\n\n            if (!this.moveController.isAnimating) {\n                // set default position\n                this.moveController.setPositionAndRotation(entity); // set next default position from server entity\n            }\n\n            // do server reconciliation on client if current player only & not blocked\n            if (this.isCurrentPlayer) {\n                //this.moveController.reconcileMove(this._entity.sequence); // set default entity position\n            }\n        });\n\n        // show entoty label\n        //this.characterLabel = this._ui.createEntityLabel(this);\n    }\n\n    public spawn() {\n        // square\n        let boxSize = 0.6;\n        const box = MeshBuilder.CreateBox(\"box\", { size: boxSize }, this._scene);\n        box.position = new Vector3(0, boxSize / 2, 0);\n        const material = new StandardMaterial(\"box-material\", this._scene);\n        material.diffuseColor = Color3.FromHexString(this.color);\n        material.specularColor = Color3.Black();\n        box.material = material;\n        box.parent = this;\n        this.playerMesh = box;\n\n        // add player shadow\n        this._shadow.addShadowCaster(box);\n    }\n\n    public update(delta: number) {\n        // only for current player\n        if (this.isCurrentPlayer) {\n            this._camera.tween(this);\n        }\n    }\n\n    public updateServerRate() {\n        if (this.isCurrentPlayer) {\n            // if space is pressed\n            if (this._input.space_pressed === true) {\n                this._room.send(ServerMsg.PLACE_BOMB);\n                this._input.space_pressed = false;\n            }\n        }\n    }\n\n    public isTileAvailable(x, z) {\n        for (let [key, element] of this._entities) {\n            if (element._entity.col === x && element._entity.row === z) {\n                return false;\n            }\n        }\n        return true;\n    }\n\n    public delete() {\n        if (this.playerMesh) {\n            this.playerMesh.dispose();\n        }\n        if (this.characterLabel) {\n            this.characterLabel.dispose();\n        }\n    }\n}\n","import { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { ServerMsg, PlayerInputs, CellType } from \"../../../../shared/types\";\nimport { Entity } from \"../Entity\";\nimport { PlayerInput } from \"./PlayerInput\";\nimport { CubicEase, EasingFunction, SineEase } from \"@babylonjs/core/Animations/easing\";\nimport { Animation } from \"@babylonjs/core/Animations/animation\";\nimport { fxaaPixelShader } from \"@babylonjs/core/Shaders/fxaa.fragment\";\nimport { Scene } from \"@babylonjs/core/scene\";\n\nexport class MoveController {\n    private _player: Entity;\n    private _mesh;\n    private speed;\n    private _input: PlayerInput;\n    private _room;\n    private _game;\n    private _scene: Scene;\n    public playerInputs: PlayerInputs[] = [];\n    private playerLatestSequence: number;\n\n    private nextPosition: Vector3;\n    private nextRotation: Vector3;\n\n    private sequence: number = 0;\n    private isCurrentPlayer: boolean = false;\n    private isMoving: boolean = false;\n\n    public isAnimating: boolean = false;\n\n    constructor(player: Entity) {\n        this._scene = player._scene;\n        this._player = player;\n        this._input = player._input;\n        this._room = player._room;\n        this._game = player._game;\n        this.isCurrentPlayer = player.isCurrentPlayer;\n    }\n\n    public getNextPosition() {\n        return this.nextPosition;\n    }\n\n    public getNextRotation() {\n        return this.nextRotation;\n    }\n\n    public setPositionAndRotation(entity): void {\n        this._player.position = new Vector3(entity.col, 0, entity.row);\n        //this._player.playerMesh.rotation = new Vector3(0, entity.rot, 0);\n    }\n\n    public tween() {\n        //this._player.position = Vector3.Lerp(this._player.position, this.nextPosition, 0.4);\n        //this._player.playerMesh.rotation = this.nextRotation;\n    }\n\n    public move(vertical, horizontal) {\n        // do not move until animation is finished\n        if (this.isAnimating) {\n            return false;\n        }\n\n        // set a few variables\n        console.log(\"[move]\", vertical, horizontal, this.isAnimating);\n        let instance = this._player.playerMesh;\n        let totalAnimationLength = 60;\n        let animationSpeed = 4;\n\n        // set angle and direction\n        let angle = Math.PI / 2;\n        let direction = \"x\";\n        if (horizontal > 0 || horizontal < 0) {\n            direction = \"z\";\n        }\n\n        if (vertical > 0 || horizontal < 0) {\n            angle = -(Math.PI / 2);\n        }\n\n        // set pivot point\n        let size = 1 / 2;\n        if (horizontal < 0) {\n            instance.setPivotPoint(new Vector3(size, -size, 0)); // left\n        }\n        if (horizontal > 0) {\n            instance.setPivotPoint(new Vector3(-size, -size, 0)); // right\n        }\n        if (vertical < 0) {\n            instance.setPivotPoint(new Vector3(0, -size, size)); // top\n        }\n        if (vertical > 0) {\n            instance.setPivotPoint(new Vector3(0, -size, -size)); // bottom\n        }\n\n        console.log(\"[move]\", angle, \"rotation.\" + direction);\n\n        // Creating an easing function\n        const easingFunction = new SineEase();\n        easingFunction.setEasingMode(EasingFunction.EASINGMODE_EASEOUT); // For each easing function, you can choose between EASEIN (default), EASEOUT, EASEINOUT\n\n        //Animate the bomb\n        const animWheel = new Animation(\"wheelAnimation\", \"rotation.\" + direction, 60, Animation.ANIMATIONTYPE_FLOAT, Animation.ANIMATIONLOOPMODE_CONSTANT);\n\n        //At the animation key 0, the value of rotation.y is 0\n        const wheelKeys = [];\n        wheelKeys.push(\n            {\n                frame: 0,\n                value: 0,\n            },\n            {\n                frame: totalAnimationLength,\n                value: angle,\n            }\n        );\n\n        //set the keys\n        animWheel.setKeys(wheelKeys);\n        animWheel.setEasingFunction(easingFunction);\n\n        //Link this animation to a bomb\n        instance.animations = [];\n        instance.animations.push(animWheel);\n\n        // calculate position\n        let newPosition = this.calculateNewPosition(horizontal, vertical);\n\n        // start animation\n        this._scene.beginAnimation(instance, 0, totalAnimationLength, false, animationSpeed, () => {\n            console.log(\"[move]\", \"ANIMATION FINISHED\", this._player.playerMesh.rotation);\n            this._player.playerMesh.rotation = new Vector3(0, 0, 0);\n            this._player.position = newPosition;\n            instance.setPivotPoint(new Vector3(0, 0, 0));\n            this.isAnimating = false;\n        });\n\n        console.log(\"[move]\", \"ANIMATION STARTED\");\n        this.isAnimating = true;\n    }\n\n    public calculateNewPosition(horizontal, vertical): Vector3 {\n        let speed = 1;\n        let newCol = this._player.position.x - horizontal * speed;\n        let newRow = this._player.position.z - vertical * speed;\n        return new Vector3(newCol, 0, newRow);\n    }\n\n    public processMove() {\n        console.log(\"[move]\", \"PROCESS MOVE\");\n        // detect movement\n        if (!this.isAnimating) {\n            console.log(\"[move]\", \"CAN PROCESS MOVE\");\n            // increment seq\n            this.sequence++;\n\n            // prepare input to be sent\n            let latestInput = {\n                seq: this.sequence,\n                h: this._player._input.horizontal,\n                v: this._player._input.vertical,\n            };\n\n            if (this.canMove(latestInput)) {\n                console.log(\"[move]\", \"NAVMESH PASS\");\n                // sent current input to server for processing\n                this._room.send(ServerMsg.PLAYER_MOVE, latestInput);\n\n                // do client side prediction\n                this.predictionMove(latestInput);\n            } else {\n                console.log(\"[move]\", \"NAVMESH DENIED\");\n                this._player._input.player_can_move = false;\n                this._player._input.horizontal = 0;\n                this._player._input.vertical = 0;\n            }\n        }\n    }\n\n    // prediction move\n    public predictionMove(latestInput: PlayerInputs) {\n        // move player locally\n        this.move(latestInput.v, latestInput.h);\n\n        // Save this input for later reconciliation.\n        this.playerInputs.push(latestInput);\n    }\n\n    // server Reconciliation. Re-apply all the inputs not yet processed by the server\n    public reconcileMove(latestSequence) {\n        // store latest sequence processed by server\n        this.playerLatestSequence = latestSequence;\n\n        // if nothing to apply, do nothin\n        if (!this.playerInputs.length) return false;\n\n        var j = 0;\n        while (j < this.playerInputs.length) {\n            var nextInput = this.playerInputs[j];\n\n            if (nextInput.seq <= this.playerLatestSequence) {\n                // Already processed. Its effect is already taken into account into the world update\n                // we just got, so we can drop it.\n                this.playerInputs.splice(j, 1);\n            } else {\n                // Not processed by the server yet. Re-apply it.\n                this.move(nextInput.v, nextInput.h);\n                j++;\n            }\n        }\n    }\n\n    public canMove(playerInput) {\n        let newPosition = this.calculateNewPosition(playerInput.h, playerInput.v);\n        let cell = this._room.state.cells.get(newPosition.z + \"-\" + newPosition.x);\n        if (cell && cell.type === CellType.GROUND) {\n            return true;\n        }\n        return false;\n    }\n\n    /*\n\n    // prediction move\n    public predictionMove(latestInput: PlayerInputs) {\n        // move player locally\n        this.move(latestInput);\n\n        // Save this input for later reconciliation.\n        this.playerInputs.push(latestInput);\n    }\n\n    //\n    public processMove() {\n        // detect movement\n        if (this._input.player_can_move) {\n            // increment seq\n            this.sequence++;\n\n            // prepare input to be sent\n            let latestInput = {\n                seq: this.sequence,\n                h: this._input.horizontal,\n                v: this._input.vertical,\n            };\n\n            // send to server\n            this._room.send(ServerMsg.PLAYER_MOVE, latestInput);\n\n            \n            if (this.canMove(latestInput)) {\n                // sent current input to server for processing\n                this._room.send(ServerMsg.PLAYER_MOVE, latestInput);\n\n                // do client side prediction\n                this.predictionMove(latestInput);\n            }\n        }\n    }\n\n    public canMove(playerInput) {\n        let speed = 1;\n        let newCol = this.nextPosition.x - playerInput.h * speed;\n        let newRow = this.nextPosition.z - playerInput.v * speed;\n        let cell = this._room.state.cells.get(newRow + \"-\" + newCol);\n        if (cell && cell.type === CellType.GROUND) {\n            return true;\n        }\n        return false;\n    }\n\n    public move(playerInput: PlayerInputs): void {\n        // calculate position\n        let speed = 1;\n        let newCol = this.nextPosition.x - playerInput.h * speed;\n        let newRow = this.nextPosition.z - playerInput.v * speed;\n        const newRotY = Math.atan2(playerInput.h, playerInput.v);\n        // apply new position\n        this.nextPosition.x = newCol;\n        this.nextPosition.z = newRow;\n        this.nextRotation.y = this.nextRotation.y + (newRotY - this.nextRotation.y);\n\n        \n        if (this.isCurrentPlayer && this.canMove(playerInput)) {\n            // calculate position\n            let speed = 1;\n            let newCol = this.nextPosition.x - playerInput.h * speed;\n            let newRow = this.nextPosition.z - playerInput.v * speed;\n            const newRotY = Math.atan2(playerInput.h, playerInput.v);\n            // apply new position\n            this.nextPosition.x = newCol;\n            this.nextPosition.z = newRow;\n            this.nextRotation.y = this.nextRotation.y + (newRotY - this.nextRotation.y);\n        }\n        \n    }\n\n    \n    public tween() {\n        this._player.position = Vector3.Lerp(this._player.position, this.nextPosition, 0.5);\n        this._player.playerMesh.rotation = this.nextRotation;\n    }*/\n}\n","import { KeyboardEventTypes } from \"@babylonjs/core/Events/keyboardEvents\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { Entity } from \"../Entity\";\nimport { Room } from \"colyseus.js\";\nimport { MoveController } from \"./MoveController\";\n\nexport class PlayerInput {\n    private _scene: Scene;\n    private _room: Room;\n    private _moveController: MoveController;\n\n    public vertical: number = 0;\n    public horizontal: number = 0;\n\n    public player_can_move: boolean = false;\n    public space_pressed: boolean = false;\n    public debug_pressed: boolean = false;\n\n    constructor(entity: Entity) {\n        this._moveController = entity.moveController;\n        this._scene = entity._scene;\n        this._room = entity._room;\n\n        console.log(\"[PlayerInput]\", entity);\n\n        this._scene.onKeyboardObservable.add((kbInfo: { type: any; event: { code: string } }) => {\n            switch (kbInfo.type) {\n                case KeyboardEventTypes.KEYDOWN:\n                    // if\n                    if (kbInfo.event.code === \"ArrowUp\" || kbInfo.event.code === \"KeyW\") {\n                        this.vertical = -1;\n                    } else if (kbInfo.event.code === \"ArrowDown\" || kbInfo.event.code === \"KeyS\") {\n                        this.vertical = 1;\n                    } else if (kbInfo.event.code === \"ArrowRight\" || kbInfo.event.code === \"KeyD\") {\n                        this.horizontal = -1;\n                    } else if (kbInfo.event.code === \"ArrowLeft\" || kbInfo.event.code === \"KeyA\") {\n                        this.horizontal = 1;\n                    }\n\n                    if (kbInfo.event.code === \"Space\") {\n                        this.space_pressed = true;\n                    }\n                    if (kbInfo.event.code === \"KeyD\") {\n                        this.debug_pressed = true;\n                    }\n\n                    break;\n\n                case KeyboardEventTypes.KEYUP:\n                    // if\n                    if (kbInfo.event.code === \"ArrowUp\" || kbInfo.event.code === \"KeyW\") {\n                        this.vertical = 0;\n                    } else if (kbInfo.event.code === \"ArrowDown\" || kbInfo.event.code === \"KeyS\") {\n                        this.vertical = 0;\n                    } else if (kbInfo.event.code === \"ArrowRight\" || kbInfo.event.code === \"KeyD\") {\n                        this.horizontal = 0;\n                    } else if (kbInfo.event.code === \"ArrowLeft\" || kbInfo.event.code === \"KeyA\") {\n                        this.horizontal = 0;\n                    }\n                    if (kbInfo.event.code === \"Space\") {\n                        this.space_pressed = false;\n                    }\n                    if (kbInfo.event.code === \"KeyD\") {\n                        this.debug_pressed = false;\n                    }\n\n                    break;\n            }\n\n            if (this.horizontal !== 0 || this.vertical !== 0) {\n                console.log(\"[INPUT]\", this.horizontal, this.vertical !== 0);\n                this.player_can_move = true;\n                this._moveController.processMove();\n            } else {\n                this.player_can_move = false;\n            }\n        });\n    }\n}\n","import { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { Animation } from \"@babylonjs/core/Animations/animation\";\nimport { TransformNode } from \"@babylonjs/core/Meshes/transformNode\";\nimport { CellType } from \"../../../shared/types\";\nimport { ParticleSystem } from \"@babylonjs/core/Particles/particleSystem\";\nimport { Color3, Color4 } from \"@babylonjs/core/Maths/math.color\";\nimport { Texture } from \"@babylonjs/core/Materials/Textures/texture\";\nimport { Sound } from \"@babylonjs/core/Audio/sound\";\nimport { MeshBuilder } from \"@babylonjs/core/Meshes/meshBuilder\";\nimport { StandardMaterial } from \"@babylonjs/core/Materials/standardMaterial\";\nimport { Material } from \"@babylonjs/core/Materials/material\";\nimport { Engine } from \"@babylonjs/core/Engines/engine\";\n\nexport class Explosion extends TransformNode {\n    public _generator;\n    public _map;\n    public _room;\n    public _camera;\n    public _entities;\n\n    public playerMesh;\n    public mesh1;\n    public mesh2;\n\n    public type: CellType;\n    public size: number = 1;\n    public tile;\n    public col: number = 0;\n    public row: number = 0;\n    public cells: [] = [];\n\n    public texture;\n    public animWheel;\n    public decals = [];\n\n    constructor(name: string, scene: Scene, map, generator, entities, camera, data) {\n        super(name, scene);\n\n        // set variables\n        this._entities = entities;\n        this._scene = scene;\n        this._map = map;\n        this._generator = generator;\n        this._camera = camera;\n\n        // set entity\n        Object.assign(this, data);\n\n        // set tile\n        this.tile = this._map.findTile(this.type, \"name\");\n\n        // set position\n        this.setPosition();\n\n        // spawn\n        this.spawn();\n    }\n\n    public spawn() {\n        // add camera shake\n        this._camera.shake();\n\n        // for every direction\n        for (let x in this.cells) {\n            let dir = this.cells[x] as any;\n            let row = dir.row;\n            let col = dir.col;\n\n            // show explosion\n            let newRow = row - this.row;\n            let newCol = col - this.col;\n\n            // create explosion emitter\n            let instance = this._generator.assets[\"explosion\"].createInstance(\"exp-\" + row + \"-\" + col);\n            instance.position = new Vector3(newCol, 0, newRow);\n            instance.parent = this;\n            instance.isVisible = true;\n\n            // add particule system\n            var particleSystem = this._generator.assets[\"particleSystem\"].clone();\n            particleSystem.emitter = instance; // the starting location\n            particleSystem.start();\n\n            // add decal\n            /*\n            newRow = row;\n            newCol = col;\n            let cell = this._entities.get(newRow + \"-\" + newCol);\n            let decal;\n            console.log(\"LOOKING FOR CELL\", newRow + \"-\" + newCol);\n            if (cell) {\n                console.log(\"ADDING DECAL AT\", cell.id);\n                // adding decal\n                let decalMaterial = this._scene.getMaterialByName(\"explosionDecal\") as StandardMaterial;\n                if (!decalMaterial) {\n                    decalMaterial = new StandardMaterial(\"explosionDecal\");\n                    decalMaterial.diffuseColor = new Color3(0, 0, 0);\n                    decalMaterial.specularColor = Color3.Black();\n                    decalMaterial.opacityTexture = new Texture(\"textures/blast_opacity.png\");\n                }\n\n                decal = MeshBuilder.CreateGround(\"decal\", { width: 1, height: 1 });\n                decal.position = cell.position;\n                decal.position.y += 0.05;\n                decal.material = decalMaterial;\n\n                //Animate the bomb\n                const animWheel = new Animation(\"wheelAnimation\", \"visibility\", 60, Animation.ANIMATIONTYPE_FLOAT, Animation.ANIMATIONLOOPMODE_CYCLE);\n                const wheelKeys = [];\n                wheelKeys.push({ frame: 0, value: 1 });\n                wheelKeys.push({ frame: 60, value: 0 });\n                wheelKeys.push({ frame: 120, value: 1 });\n                animWheel.setKeys(wheelKeys);\n                instance.animations = [];\n                instance.animations.push(animWheel);\n                console.log(\"DECAL STARTED\");\n                this._scene.beginAnimation(decal, 0, 600, true, 1, () => {\n                    console.log(\"DECAL FINISHED\");\n                    //decal.dispose();\n                });\n            }\n            */\n\n            // play epxlosion sound\n            //this._generator.assets[\"explosionSound\"].setPosition(new Vector3(newRow, 0, newCol));\n            //this._generator.assets[\"explosionSound\"].setVolume(0.1);\n            //this._generator.assets[\"explosionSound\"].play();\n\n            // remove\n            setTimeout(() => {\n                //decal.dispose();\n                particleSystem.dispose(true);\n                instance.dispose();\n            }, 2000);\n        }\n    }\n\n    // obsolete???\n    public _spawn() {\n        const dirs = [\n            {\n                // up\n                col: -1,\n                row: 0,\n                direction: \"left\",\n            },\n            {\n                // down\n                col: 1,\n                row: 0,\n                direction: \"righ\",\n            },\n            {\n                // left\n                col: 0,\n                row: -1,\n                direction: \"down\",\n            },\n            {\n                // right\n                col: 0,\n                row: 1,\n                direction: \"up\",\n            },\n        ];\n        let addedMiddleCell = false;\n\n        // add camera shake\n        this._camera.shake();\n\n        // for every direction\n        dirs.forEach((dir) => {\n            // for distance\n            for (let i = 0; i <= this.size; i++) {\n                const col = this.col + dir.col * i;\n                const row = this.row + dir.row * i;\n\n                // get cell\n                const cell = this._room.state.cells.get(row + \"-\" + col);\n\n                // dont show explosion on hard walls\n                if (cell.type === CellType.WALL) {\n                    console.log(\"--> is a wall, return\");\n                    return;\n                }\n\n                // dont show explosion on soft walls\n                if (cell.type === CellType.BREAKABLE_WALL) {\n                    console.log(\"--> is a breakable wall, return\");\n                    return;\n                }\n\n                if (i === 0 && addedMiddleCell) {\n                    console.log(\"--> already added the middle cell\");\n                    continue;\n                }\n\n                // show explosion\n                let newRow = row - this.row;\n                let newCol = col - this.col;\n                console.log(\"--> add explosion\", newRow, newCol);\n                let instance = this._generator.assets[\"explosion\"].clone(\"exp-\" + row + \"-\" + col);\n                instance.position = new Vector3(newCol, 0, newRow);\n                instance.receiveShadows = true;\n                instance.parent = this;\n                instance.isVisible = true;\n\n                //Animate the bomb\n                instance.animations = [];\n                instance.animations.push(this.animWheel);\n                this._scene.beginAnimation(instance, 0, 60, true);\n\n                // add particule system\n                //////////////////////////////////////////////\n                // create a particle system\n                var particleSystem = new ParticleSystem(\"particles\", 1000, this._scene);\n                particleSystem.particleTexture = this.texture;\n                particleSystem.emitter = instance; // the starting location\n                // Colors of all particles\n                particleSystem.color1 = Color4.FromHexString(\"#f58d42\");\n                particleSystem.color2 = Color4.FromHexString(\"#ff1900\");\n                particleSystem.colorDead = new Color4(0, 0, 0, 1);\n                // Size of each particle (random between...\n                particleSystem.minSize = 0.3;\n                particleSystem.maxSize = 0.6;\n                // Life time of each particle (random between...\n                particleSystem.minLifeTime = 1;\n                particleSystem.maxLifeTime = 1.5;\n                particleSystem.targetStopDuration = 1.5;\n                // Emission rate\n                particleSystem.emitRate = 1000;\n                particleSystem.createSphereEmitter(1);\n\n                particleSystem.updateSpeed = 0.1;\n                // Start the particle system\n                particleSystem.start();\n                //////////////////////////////////////////////\n\n                setTimeout(() => {\n                    particleSystem.dispose(true);\n                }, 1000);\n\n                //\n                if (i === 0 && !addedMiddleCell) {\n                    addedMiddleCell = true;\n                }\n            }\n        });\n    }\n\n    public setPosition() {\n        this.position = new Vector3(this.col, 0, this.row);\n    }\n\n    public delete() {}\n}\n","import { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { Scene } from \"@babylonjs/core/scene\";\nimport { Animation } from \"@babylonjs/core/Animations/animation\";\nimport { TransformNode } from \"@babylonjs/core/Meshes/transformNode\";\nimport { CellType } from \"../../../shared/types\";\nimport { ParticleSystem } from \"@babylonjs/core/Particles/particleSystem\";\nimport { Color3, Color4 } from \"@babylonjs/core/Maths/math.color\";\nimport { Texture } from \"@babylonjs/core/Materials/Textures/texture\";\nimport { Sound } from \"@babylonjs/core/Audio/sound\";\nimport { MeshBuilder } from \"@babylonjs/core/Meshes/meshBuilder\";\nimport { StandardMaterial } from \"@babylonjs/core/Materials/standardMaterial\";\nimport { Material } from \"@babylonjs/core/Materials/material\";\nimport { Engine } from \"@babylonjs/core/Engines/engine\";\n\nexport class PowerUp extends TransformNode {\n    public _entity;\n    public _map;\n    public _room;\n    public _camera;\n    public _entities;\n    public _generator;\n\n    public type: CellType;\n    public size: number = 1;\n    public tile;\n    public col: number = 0;\n    public row: number = 0;\n    public cells: [] = [];\n    public power;\n\n    public playerMesh;\n\n    constructor(name: string, scene: Scene, gameScene, entity) {\n        super(name, scene);\n\n        // set variables\n        this._scene = scene;\n        this._map = gameScene._map;\n        this._room = gameScene.room;\n        this._generator = gameScene._generator;\n        this._entity = entity;\n\n        // set entity\n        Object.assign(this, entity);\n\n        // set position\n        this.setPosition();\n\n        // spawn\n        this.spawn();\n\n        console.log(\"POWER UP CREATE\", entity);\n    }\n\n    public spawn() {\n        // create mesh\n        let mesh = this._generator.assets[\"powerup\"];\n        let instance = mesh.clone(\"powerup-\" + this.col + \"-\" + this.row);\n        instance.parent = this;\n        instance.material = this._scene.getMaterialByName(\"powerup_\" + this.power);\n        this.playerMesh = instance;\n    }\n\n    public update() {}\n\n    public updateServerRate() {}\n\n    public setPosition() {\n        this.position = new Vector3(this.col, 0, this.row);\n    }\n\n    public delete() {\n        if (this.playerMesh) {\n            this.playerMesh.dispose();\n        }\n    }\n}\n","import { Scene } from \"@babylonjs/core/scene\";\nimport { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { Color4 } from \"@babylonjs/core/Maths/math.color\";\n\nimport { GameController } from \"../Controllers/GameController\";\nimport { CellType, SceneName, ServerMsg } from \"../../../shared/types\";\nimport { MapHelper } from \"../../../shared/MapHelper\";\nimport { Engine } from \"@babylonjs/core/Engines/engine\";\nimport { HemisphericLight } from \"@babylonjs/core/Lights/hemisphericLight\";\nimport { LevelGenerator } from \"../Controllers/LevelGenerator\";\nimport { PlayerCamera } from \"../Controllers/PlayerCamera\";\nimport { Entity } from \"../Entities/Entity\";\nimport { PlayerUI } from \"../Controllers/PlayerUI\";\nimport { DirectionalLight } from \"@babylonjs/core/Lights/directionalLight\";\nimport { ShadowGenerator } from \"@babylonjs/core/Lights/Shadows/shadowGenerator\";\nimport { Cell } from \"../Entities/Cell\";\nimport { MeshBuilder } from \"@babylonjs/core/Meshes/meshBuilder\";\nimport { Bomb } from \"../Entities/Bomb\";\nimport { PowerUp } from \"../Entities/PowerUp\";\nimport { Explosion } from \"../Entities/Explosion\";\nimport { SkyMaterial } from \"@babylonjs/materials/sky/skyMaterial\";\n\nexport class GameScene {\n    public _game: GameController;\n    public _scene: Scene;\n    public _engine: Engine;\n    public _newState: SceneName;\n    public _ui;\n    public _environment;\n    public _shadow: ShadowGenerator;\n    public _map: MapHelper;\n    public _generator: LevelGenerator;\n    public _camera: PlayerCamera;\n    public room;\n    public sessionId;\n    public entities = new Map();\n\n    constructor() {\n        this._newState = SceneName.NULL;\n    }\n\n    async createScene(game): Promise<void> {\n        // app\n        this._game = game;\n        this._engine = this._game.engine;\n\n        // create scene\n        let scene = new Scene(this._game.engine);\n\n        // set scene\n        this._scene = scene;\n\n        //\n        this._game.engine.displayLoadingUI();\n\n        // set sky color\n        this._scene.clearColor = new Color4(0.1, 0.1, 0.1, 1);\n\n        // This creates directional light with shdaows\n        var light = new DirectionalLight(\"dir01\", new Vector3(-0.25, -1, -0.25), scene);\n        light.position = new Vector3(20, 40, 20);\n        light.shadowEnabled = true;\n\n        // Shadows\n        var shadowGenerator = new ShadowGenerator(1024, light);\n        shadowGenerator.filter = ShadowGenerator.FILTER_PCF;\n        shadowGenerator.filteringQuality = ShadowGenerator.QUALITY_HIGH;\n        shadowGenerator.darkness = 0;\n        this._shadow = shadowGenerator;\n\n        // This creates a light, aiming 0,1,0 - to the sky (non-mesh)\n        var ambient = new HemisphericLight(\"ambient1\", new Vector3(0, 1, 0), scene);\n        ambient.intensity = 0.8;\n\n        const skyMaterial = new SkyMaterial(\"skyMaterial\", scene);\n        skyMaterial.backFaceCulling = false;\n\n        const skybox = MeshBuilder.CreateBox(\"skyBox\", { size: 1000.0 }, scene);\n        skybox.material = skyMaterial;\n\n        // generate level\n        let chosenMap = this._game.selectedMap.key;\n        this._map = new MapHelper(chosenMap);\n        this._generator = new LevelGenerator(this._scene, this._map, shadowGenerator);\n        await this._generator.loadModels();\n\n        // start camera\n        this._camera = new PlayerCamera(this._scene);\n\n        // setup colyseus room\n        // hack for devlopement\n        if (!this._game.joinedRoom) {\n            let hash = window.location.hash.substring(1);\n            this._game.joinedRoom = await this._game.client.createOrJoin(hash, this._game.user);\n            this._game.joinedRoom.send(ServerMsg.START_GAME_REQUESTED);\n        }\n\n        // set room\n        this.room = this._game.joinedRoom;\n        this.sessionId = this.room.sessionId;\n\n        // hide loading screen\n        setTimeout(() => {\n            this._game.engine.hideLoadingUI();\n            this.startGame();\n        }, 500);\n    }\n\n    startGame() {\n        // start UI\n        this._ui = new PlayerUI(this._scene, this._engine, this);\n\n        ///////////////////////////////////////////////////////////////////////////\n        /////////////////////////// COLYSEUS STATE\n\n        ////////////////////// PLAYERS\n        // on new player\n        this.room.state.players.onAdd((entity, sessionId) => {\n            console.log(\"[GAME] PLAYER ADDED\", entity);\n            let currentPlayer = sessionId === this.sessionId;\n            if (currentPlayer) {\n                let player = new Entity(sessionId, this._scene, this, entity, currentPlayer);\n                this._ui.setCurrentPlayer(player);\n                this.entities.set(sessionId, player);\n            } else {\n                this.entities.set(sessionId, new Entity(sessionId, this._scene, this, entity, currentPlayer));\n            }\n        });\n        this.room.state.players.onRemove((entity, sessionId) => {\n            console.log(\"[GAME] PLAYER LEFT\", entity);\n            if (this.entities.get(sessionId)) {\n                this.entities.get(sessionId).delete();\n            }\n            this.entities.delete(sessionId);\n        });\n\n        ////////////////////// CELLS\n        // on new entity\n        this.room.state.cells.onAdd((entity, sessionId) => {\n            this.entities.set(sessionId, new Cell(sessionId, this._scene, this, entity));\n        });\n        this.room.state.cells.onRemove((entity, sessionId) => {\n            if (this.entities.get(sessionId)) {\n                this.entities.get(sessionId).delete();\n            }\n            this.entities.delete(sessionId);\n        });\n\n        ////////////////////// BOMBS\n        // on new entity\n        this.room.state.bombs.onAdd((entity, sessionId) => {\n            this.entities.set(sessionId, new Bomb(sessionId, this._scene, this, entity));\n        });\n        this.room.state.bombs.onRemove((entity, sessionId) => {\n            setTimeout(() => {\n                if (this.entities.get(sessionId)) {\n                    this.entities.get(sessionId).delete();\n                }\n                this.entities.delete(sessionId);\n            }, 200);\n        });\n\n        ////////////////////// POWER UPS\n        // on new entity\n        this.room.state.powers.onAdd((entity, sessionId) => {\n            this.entities.set(sessionId, new PowerUp(sessionId, this._scene, this, entity));\n        });\n        this.room.state.powers.onRemove((entity, sessionId) => {\n            if (this.entities.get(sessionId)) {\n                this.entities.get(sessionId).delete();\n            }\n            this.entities.delete(sessionId);\n        });\n\n        ////////////////////// END COLYSEUS STATE\n        /////////////////////////////////////////////////////////////////////////////\n\n        this.room.onMessage(ServerMsg.DO_EXPLOSION, (message) => {\n            console.log(ServerMsg[ServerMsg.DO_EXPLOSION], message);\n            let exp = new Explosion(\"explosion\", this._scene, this._map, this._generator, this.entities, this._camera, message);\n            setTimeout(() => {\n                exp.delete();\n            }, 1000);\n        });\n\n        // start game event\n        this.room.onMessage(ServerMsg.START_GAME, (message) => {\n            console.log(ServerMsg[ServerMsg.START_GAME], message);\n        });\n\n        // player eliminated\n        this.room.onMessage(ServerMsg.PLAYER_ELIMINATED, (message) => {\n            console.log(\"[GAME] Player eliminated:\", message.name);\n        });\n\n        // game over - report winner to parent frame\n        this.room.onMessage(ServerMsg.GAME_OVER, (message) => {\n            console.log(\"[GAME] GAME OVER! Winner:\", message.winner);\n            const isWinner = message.winnerSessionId === this.sessionId;\n\n            // Report to parent frame (betting.html)\n            if (window.parent !== window) {\n                window.parent.postMessage({\n                    type: \"bomberman_game_over\",\n                    winner: message.winner,\n                    winnerSessionId: message.winnerSessionId,\n                    isLocalWinner: isWinner,\n                }, \"*\");\n            }\n        });\n\n        ////////////////////////////////////////////////////\n        // main game loop\n\n        const lastUpdates = {\n            SERVER: Date.now(),\n            SLOW: Date.now(),\n            PING: Date.now(),\n        };\n\n        this._scene.registerBeforeRender(() => {\n            let delta = this._engine.getFps();\n            const currentTime = Date.now();\n\n            // game update loop\n            this.entities.forEach((entity) => {\n                // 60 fps\n                entity.update(delta);\n\n                // server rate\n                if (currentTime - lastUpdates[\"SERVER\"] >= 100) {\n                    entity.updateServerRate(100);\n                }\n\n                // slow rate\n                if (currentTime - lastUpdates[\"SLOW\"] >= 100) {\n                    entity.updateServerRate(100);\n                }\n            });\n\n            // reset timers for entities\n            if (currentTime - lastUpdates[\"SERVER\"] >= 100) {\n                lastUpdates[\"SERVER\"] = currentTime;\n            }\n            if (currentTime - lastUpdates[\"SLOW\"] >= 1000) {\n                lastUpdates[\"SLOW\"] = currentTime;\n            }\n\n            // game update loop\n            if (currentTime - lastUpdates[\"PING\"] >= 1000) {\n                // send ping to server\n                this.room.send(ServerMsg.PING);\n                lastUpdates[\"PING\"] = currentTime;\n            }\n        });\n    }\n}\n","import { Scene } from \"@babylonjs/core/scene\";\nimport { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { Color4 } from \"@babylonjs/core/Maths/math.color\";\nimport { FreeCamera } from \"@babylonjs/core/Cameras/freeCamera\";\n\nimport { AdvancedDynamicTexture } from \"@babylonjs/gui/2D/advancedDynamicTexture\";\nimport { Rectangle } from \"@babylonjs/gui/2D/controls/rectangle\";\nimport { TextBlock } from \"@babylonjs/gui/2D/controls/textBlock\";\nimport { Control } from \"@babylonjs/gui/2D/controls/control\";\nimport { Button } from \"@babylonjs/gui/2D/controls/button\";\nimport { InputText } from \"@babylonjs/gui/2D/controls/inputText\";\nimport { Image } from \"@babylonjs/gui/2D/controls/image\";\n\nimport { GameController } from \"../Controllers/GameController\";\nimport { SceneName } from \"../../../shared/types\";\nimport { ScrollViewer } from \"@babylonjs/gui/2D/controls/scrollViewers/scrollViewer\";\nimport { Grid } from \"@babylonjs/gui/2D/controls/grid\";\nimport { RoomAvailable } from \"colyseus.js/lib/Room\";\nimport { StackPanel } from \"@babylonjs/gui/2D/controls/stackPanel\";\n\nexport class HomeScene {\n    private _game: GameController;\n    public _scene: Scene;\n    public _newState: SceneName;\n    public _ui;\n\n    // ui\n    public lobbyScroller: ScrollViewer;\n    public lobbyStackPanel: StackPanel;\n\n    // lobby\n    public lobbyJoined;\n    public allRooms: RoomAvailable[] = [];\n\n    constructor() {\n        this._newState = SceneName.NULL;\n    }\n\n    async createScene(game): Promise<void> {\n        // app\n        this._game = game;\n\n        // create scene\n        let scene = new Scene(this._game.engine);\n\n        // set scene\n        this._scene = scene;\n\n        // hide loading screen\n        this._game.engine.hideLoadingUI();\n\n        // set sky color\n        this._scene.clearColor = new Color4(0.1, 0.1, 0.1, 1);\n\n        //creates and positions a free camera\n        let camera = new FreeCamera(\"camera1\", new Vector3(0, 0, 0), this._scene);\n        camera.setTarget(Vector3.Zero()); //targets the camera to scene origin\n\n        // create ui\n        const guiMenu = AdvancedDynamicTexture.CreateFullscreenUI(\"UI\");\n        this.create(guiMenu);\n\n        // setup colyseus lobby\n        this.events();\n    }\n\n    async events() {\n        // join loby\n        this._game.client.joinLobby().then((lobbyJoined) => {\n            this.lobbyJoined = lobbyJoined;\n\n            // all rooms\n            this.lobbyJoined.onMessage(\"rooms\", (rooms: []) => {\n                this.allRooms = rooms;\n                this.loadRooms();\n            });\n\n            // any updates\n            this.lobbyJoined.onMessage(\"+\", ([roomId, room]) => {\n                const roomIndex = this.allRooms.findIndex((room) => room.roomId === roomId);\n                if (roomIndex !== -1) {\n                    this.allRooms[roomIndex] = room;\n                } else {\n                    this.allRooms.push(room);\n                }\n\n                // remove any locked rooms\n                if (room.locked) {\n                    this.allRooms = this.allRooms.filter((room) => room.roomId !== roomId);\n                }\n\n                this.loadRooms();\n            });\n\n            this.lobbyJoined.onMessage(\"-\", (roomId) => {\n                this.allRooms = this.allRooms.filter((room) => room.roomId !== roomId);\n                this.loadRooms();\n            });\n        });\n    }\n\n    loadRooms() {\n        // if already exists\n        this.lobbyStackPanel.getDescendants().forEach((el) => {\n            el.dispose();\n        });\n\n        if (this.allRooms.length > 0) {\n            const tableHeader = new Rectangle(\"tableHeader\");\n            tableHeader.width = 1;\n            tableHeader.height = \"20px\";\n            tableHeader.thickness = 0;\n            tableHeader.background = \"transparent\";\n            tableHeader.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n            this.lobbyStackPanel.addControl(tableHeader);\n\n            const col1Text = new TextBlock(\"col1Text\", \"#\");\n            col1Text.width = \"33%\";\n            col1Text.left = \"5%\";\n            col1Text.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n            col1Text.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n            tableHeader.addControl(col1Text);\n\n            const col2Text = new TextBlock(\"col2Text\", \"MAP\");\n            col2Text.width = \"33%\";\n            col2Text.left = \"33%\";\n            col2Text.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n            col2Text.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n            tableHeader.addControl(col2Text);\n\n            const col3Text = new TextBlock(\"col3Text\", \"PLAYERS\");\n            col3Text.width = \"33%\";\n            col3Text.left = \"66%\";\n            col3Text.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n            col3Text.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n            tableHeader.addControl(col3Text);\n\n            // add room\n            this.allRooms.forEach((room: any) => {\n                const tableHeader = new Rectangle(\"tableHeader\");\n                tableHeader.width = 1;\n                tableHeader.height = \"50px\";\n                tableHeader.background = \"#f6f8fc\";\n                tableHeader.fontSizeInPixels = 20;\n                tableHeader.thickness = 1;\n                tableHeader.color = \"#222\";\n                tableHeader.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                this.lobbyStackPanel.addControl(tableHeader);\n\n                const col1Text = new TextBlock(\"col1Text\", room.roomId);\n                col1Text.width = \"33%\";\n                col1Text.left = \"5%\";\n                col1Text.color = \"black\";\n                col1Text.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                col1Text.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                tableHeader.addControl(col1Text);\n\n                const col2Text = new TextBlock(\"col2Text\", room.metadata.map);\n                col2Text.width = \"33%\";\n                col2Text.left = \"33%\";\n                col2Text.color = \"black\";\n                col2Text.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                col2Text.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                tableHeader.addControl(col2Text);\n\n                const col3Text = new TextBlock(\"col3Text\", room.clients + \"/\" + room.maxClients);\n                col3Text.width = \"33%\";\n                col3Text.left = \"66%\";\n                col3Text.color = \"black\";\n                col3Text.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                col3Text.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n                tableHeader.addControl(col3Text);\n\n                tableHeader.onPointerUpObservable.add(async () => {\n                    this._game.client.join(room.roomId, this._game.user.displayName).then((joinedRoom) => {\n                        this.lobbyJoined.leave();\n                        setTimeout(() => {\n                            this._game.joinedRoom = joinedRoom;\n                            this._game.setScene(SceneName.ROOM);\n                        }, 200);\n                    });\n                });\n            });\n        } else {\n            // no rooms text\n            const welcomeText = new TextBlock(\"infotext\", \"No rooms available...\");\n            welcomeText.width = 0.8;\n            welcomeText.height = \"30px\";\n            welcomeText.top = \"30px\";\n            welcomeText.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n            welcomeText.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n            this.lobbyStackPanel.addControl(welcomeText);\n        }\n    }\n\n    create(guiMenu) {\n        let padding = 10;\n\n        // full width\n        const fullWidth = new Rectangle(\"fullwidth\");\n        fullWidth.width = 1;\n        fullWidth.height = 1;\n        fullWidth.thickness = 0;\n        fullWidth.background = \"#222222\";\n        fullWidth.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        fullWidth.fontFamily = this._game.config.fontFamily;\n        guiMenu.addControl(fullWidth);\n\n        // middle columm\n        const columnRect = new Rectangle(\"column\");\n        columnRect.width = \"400px\";\n        columnRect.height = 1;\n        columnRect.background = \"transparent\";\n        columnRect.thickness = 0;\n        columnRect.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        fullWidth.addControl(columnRect);\n\n        const grid = new Grid();\n        grid.addColumnDefinition(1);\n        grid.addRowDefinition(120, true);\n        grid.addRowDefinition(80, true);\n        grid.addRowDefinition(padding, true);\n        grid.addRowDefinition(0.7);\n        grid.addRowDefinition(padding, true);\n        columnRect.addControl(grid);\n\n        // This rect will be on first row and second column\n        const header = new Rectangle();\n        header.background = \"transparent\";\n        header.thickness = 0;\n        grid.addControl(header, 0);\n\n        // This rect will be on second row and third column\n        const formBloc = new Rectangle();\n        formBloc.background = \"white\";\n        formBloc.thickness = 0;\n        grid.addControl(formBloc, 1);\n\n        const mainBloc = new Rectangle();\n        mainBloc.background = \"white\";\n        mainBloc.thickness = 0;\n        grid.addControl(mainBloc, 3);\n\n        ///////////////////////////////////////////////////////\n        // header\n\n        // logo\n        var imgLogo = new Image(\"imgLogo\", \"./images/logo.png\");\n        imgLogo.stretch = Image.STRETCH_UNIFORM;\n        imgLogo.top = \"10px\";\n        imgLogo.width = 1;\n        imgLogo.height = \"70px;\";\n        imgLogo.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        header.addControl(imgLogo);\n\n        // welcome text\n        const welcomeText = new TextBlock(\"infotext\", this._game.config.version);\n        welcomeText.width = 0.8;\n        welcomeText.height = \"30px\";\n        welcomeText.color = \"white\";\n        welcomeText.top = \"80px\";\n        welcomeText.fontSizeInPixels = 14;\n        welcomeText.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        welcomeText.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        header.addControl(welcomeText);\n\n        //////////////////////////////////////////////////\n        // FORM CONTAINER columm\n        const formName = new Rectangle(\"formName\");\n        formName.background = \"white\";\n        formName.width = 1;\n        formName.height = \"80px\";\n        formName.top = \"0px\";\n        formName.thickness = 0;\n        formName.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        formName.verticalAlignment = Control.VERTICAL_ALIGNMENT_BOTTOM;\n        formBloc.addControl(formName);\n\n        // username input\n        const usernameInput = new InputText(\"usernameInput\");\n        usernameInput.top = \"-\" + padding + \"px\";\n        usernameInput.width = 1;\n        usernameInput.height = \"50px;\";\n        usernameInput.color = \"#000\";\n        usernameInput.background = \"#FFF\";\n        usernameInput.text = this._game.user.displayName;\n        usernameInput.fontSizeInPixels = 24;\n        usernameInput.focusedBackground = \"gray\";\n        usernameInput.placeholderText = \"Enter Username\";\n        usernameInput.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        usernameInput.verticalAlignment = Control.VERTICAL_ALIGNMENT_CENTER;\n        usernameInput.setPadding(padding, padding, -padding, padding);\n        formBloc.addControl(usernameInput);\n\n        usernameInput.onTextChangedObservable.add(async () => {\n            this._game.user.displayName = usernameInput.text;\n        });\n\n        //////////////////////////////////////////////////\n        // FORM CONTAINER columm\n\n        const subGrid = new Grid();\n        subGrid.addColumnDefinition(1);\n        subGrid.addRowDefinition(30, true);\n        subGrid.addRowDefinition(padding, true);\n        subGrid.addRowDefinition(1);\n        subGrid.setPadding(padding, padding, padding, padding);\n        mainBloc.addControl(subGrid);\n\n        const subHeaderGrid = new Rectangle();\n        subHeaderGrid.background = \"white\";\n        subHeaderGrid.thickness = 0;\n        subGrid.addControl(subHeaderGrid, 0);\n\n        const subMainGrid = new Rectangle();\n        subMainGrid.background = \"white\";\n        subMainGrid.thickness = 0;\n        subGrid.addControl(subMainGrid, 2);\n\n        console.log(this._game.config);\n        const createBtn = Button.CreateSimpleButton(\"createBtn\", \"CREATE\");\n        createBtn.width = 1;\n        createBtn.heightInPixels = this._game.config.button.height;\n        createBtn.color = this._game.config.button.color;\n        createBtn.background = this._game.config.button.background;\n        createBtn.textBlock.fontSizeInPixels = this._game.config.button.fontSize;\n        createBtn.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        createBtn.verticalAlignment = Control.VERTICAL_ALIGNMENT_CENTER;\n        subHeaderGrid.addControl(createBtn);\n\n        createBtn.onPointerUpObservable.add(async () => {\n            this.lobbyJoined.leave();\n            this._game.client.create(this._game.user.displayName).then((joinedRoom) => {\n                this._game.joinedRoom = joinedRoom;\n                this._game.setScene(SceneName.ROOM);\n            });\n        });\n\n        // add scrollable container\n        const lobbyScroller = new ScrollViewer(\"chatScrollViewer\");\n        lobbyScroller.width = 1;\n        lobbyScroller.height = 1;\n        lobbyScroller.top = \"0px\";\n        lobbyScroller.thickness = 1;\n        lobbyScroller.background = \"#FFF\";\n        lobbyScroller.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        lobbyScroller.verticalAlignment = Control.VERTICAL_ALIGNMENT_BOTTOM;\n        subMainGrid.addControl(lobbyScroller);\n\n        // add stack panel\n        const lobbyStackPanel = new StackPanel(\"lobbyStackPanel\");\n        lobbyStackPanel.width = \"100%\";\n        lobbyStackPanel.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        lobbyStackPanel.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        lobbyStackPanel.paddingTop = \"5px;\";\n        lobbyStackPanel.spacing = 10;\n        lobbyScroller.addControl(lobbyStackPanel);\n\n        // load scene\n        this.lobbyScroller = lobbyScroller;\n        this.lobbyStackPanel = lobbyStackPanel;\n        this._ui = guiMenu;\n    }\n}\n","import { Scene } from \"@babylonjs/core/scene\";\nimport { Vector3 } from \"@babylonjs/core/Maths/math.vector\";\nimport { Color4 } from \"@babylonjs/core/Maths/math.color\";\nimport { FreeCamera } from \"@babylonjs/core/Cameras/freeCamera\";\n\nimport { AdvancedDynamicTexture } from \"@babylonjs/gui/2D/advancedDynamicTexture\";\nimport { Rectangle } from \"@babylonjs/gui/2D/controls/rectangle\";\nimport { TextBlock } from \"@babylonjs/gui/2D/controls/textBlock\";\nimport { Control } from \"@babylonjs/gui/2D/controls/control\";\nimport { Button } from \"@babylonjs/gui/2D/controls/button\";\n\nimport { GameController } from \"../Controllers/GameController\";\nimport { SceneName, ServerMsg } from \"../../../shared/types\";\nimport { ScrollViewer } from \"@babylonjs/gui/2D/controls/scrollViewers/scrollViewer\";\nimport { Grid } from \"@babylonjs/gui/2D/controls/grid\";\nimport { StackPanel } from \"@babylonjs/gui/2D/controls/stackPanel\";\nimport { Room } from \"colyseus.js\";\nimport { MenuOptions } from \"../Utils/MenuOptions\";\nimport { title } from \"process\";\n\nexport class RoomScene {\n    private _game: GameController;\n    public _scene: Scene;\n    public _newState: SceneName;\n    public _button: Button;\n    public _ui;\n    public _shadow;\n\n    public room: Room;\n    public sessionId;\n    public players = new Map();\n\n    // ui\n    public playerStackPanel: StackPanel;\n    public mapStackPanel: StackPanel;\n\n    // calllbacks\n    public callbacksToRemove: any[] = [];\n\n    constructor() {\n        this._newState = SceneName.NULL;\n    }\n\n    async createScene(game): Promise<void> {\n        // app\n        this._game = game;\n\n        // room\n        this.room = this._game.joinedRoom as Room;\n\n        // create scene\n        let scene = new Scene(this._game.engine);\n\n        // set scene\n        this._scene = scene;\n\n        // hide loading screen\n        this._game.engine.hideLoadingUI();\n\n        // set sky color\n        this._scene.clearColor = new Color4(0.1, 0.1, 0.1, 1);\n\n        //creates and positions a free camera\n        let camera = new FreeCamera(\"camera1\", new Vector3(0, 0, 0), this._scene);\n        camera.setTarget(Vector3.Zero()); //targets the camera to scene origin\n\n        // create ui\n        const guiMenu = AdvancedDynamicTexture.CreateFullscreenUI(\"UI\");\n        this.create(guiMenu);\n\n        // setup colyseus room\n        if (this.room) {\n            window.location.hash = this.room.roomId;\n            this.sessionId = this.room.sessionId;\n            let evtOnAdd = this.room.state.players.onAdd((entity, sessionId) => {\n                console.log(\"[ROOM] PLAYER ADDED\", entity);\n                this.players.set(sessionId, entity);\n                this.updatePlayers();\n            });\n            let evtOnRemove = this.room.state.players.onRemove((entity, sessionId) => {\n                console.log(\"[ROOM] PLAYER LEFT\", sessionId);\n                this.players.delete(sessionId);\n                this.updatePlayers();\n            });\n            this.callbacksToRemove.push(evtOnAdd);\n            this.callbacksToRemove.push(evtOnRemove);\n\n            // monitor map changes\n            this.room.state.listen(\"map\", (currentValue, previousValue) => {\n                this.changeMap(currentValue);\n            });\n\n            // start game event\n            this.room.onMessage(ServerMsg.START_GAME, (message) => {\n                console.log(\"message received from server\", message);\n\n                // remove any messages events\n                this.room.removeAllListeners();\n\n                // remove onAdd and onRemove callbacks\n                this.callbacksToRemove.forEach((callback) => callback());\n\n                // go to game scene\n                this._game.setScene(SceneName.GAME);\n            });\n        }\n    }\n\n    changeMap(key) {\n        console.log(\"changeMap\", key);\n        this._game.selectedMap = this._game.maps[key];\n        this.updateMaps();\n    }\n\n    updatePlayers() {\n        console.log(\"[ROOM] REFRESH PLAYER PANEL\", this.playerStackPanel.children.length);\n\n        // if already exists\n        this.playerStackPanel.getDescendants().forEach((el) => {\n            el.dispose();\n        });\n\n        // middle columm\n        const blocGame = new Rectangle(\"totalPlayers\");\n        blocGame.width = 1;\n        blocGame.height = \"24px;\";\n        blocGame.background = \"white\";\n        blocGame.thickness = 0;\n        blocGame.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        this.playerStackPanel.addControl(blocGame);\n\n        const maxP = this._game.pvpMaxPlayers || 4;\n        const textGame = new TextBlock(\"totalPlayers\");\n        textGame.width = 1;\n        textGame.text = \"Players \" + this.players.size + \" / \" + maxP;\n        textGame.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        textGame.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        blocGame.addControl(textGame);\n\n        this.players.forEach((player) => {\n            // rect\n            const blocGame = new Rectangle(\"blocGame\" + player.sessionId);\n            blocGame.width = 1;\n            blocGame.height = \"50px;\";\n            blocGame.background = \"gray\";\n            blocGame.thickness = 0;\n            blocGame.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n            this.playerStackPanel.addControl(blocGame);\n\n            // color\n            const colorBLoc = new Rectangle(\"colorBLoc\" + player.sessionId);\n            colorBLoc.top = \"10px\";\n            colorBLoc.left = \"10px\";\n            colorBLoc.width = \"30px\";\n            colorBLoc.height = \"30px;\";\n            colorBLoc.background = player.color;\n            colorBLoc.thickness = 1;\n            colorBLoc.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n            colorBLoc.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n            blocGame.addControl(colorBLoc);\n\n            // middle columm\n            const textGame = new TextBlock(\"textGame\" + player.sessionId);\n            textGame.width = 1;\n            textGame.text = player.name;\n            textGame.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n            blocGame.addControl(textGame);\n        });\n\n        // showing available players slot\n        const maxPlayers = this._game.pvpMaxPlayers || 4;\n        for (let i = 0; i < maxPlayers - this.players.size; i++) {\n            // rect\n            const blocGame = new Rectangle(\"blocGame\" + i);\n            blocGame.width = 1;\n            blocGame.height = \"50px;\";\n            blocGame.background = \"lightgray\";\n            blocGame.thickness = 0;\n            blocGame.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n            this.playerStackPanel.addControl(blocGame);\n\n            // middle columm\n            const textGame = new TextBlock(\"textGame\" + i);\n            textGame.width = 1;\n            textGame.text = \"WAITING FOR PLAYER...\";\n            textGame.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n            blocGame.addControl(textGame);\n        }\n    }\n\n    updateMaps() {\n        console.log(\"[ROOM] REFRESH MAP PANEL\");\n\n        // if already exists\n        this.mapStackPanel.getDescendants().forEach((el) => {\n            el.dispose();\n        });\n\n        // add title\n        const textGame = new TextBlock(\"mapTitle\");\n        textGame.width = 1;\n        textGame.height = \"20px\";\n        textGame.text = \"Choose Map\";\n        textGame.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        textGame.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        textGame.textVerticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        textGame.textHorizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        this.mapStackPanel.addControl(textGame);\n\n        // add maps\n        for (let makKey in this._game.maps) {\n            let map = this._game.maps[makKey];\n\n            const mapBtn = Button.CreateSimpleButton(\"mapBtn\" + makKey, map.name);\n            mapBtn.width = \"100px\";\n            mapBtn.height = \"60px\";\n            mapBtn.color = \"black\";\n            mapBtn.background = \"white\";\n            mapBtn.thickness = 1;\n            mapBtn.fontSizeInPixels = 18;\n            mapBtn.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n            mapBtn.verticalAlignment = Control.VERTICAL_ALIGNMENT_CENTER;\n\n            if (this._game.selectedMap && this._game.selectedMap.key == map.key) {\n                mapBtn.color = \"white\";\n                mapBtn.background = this._game.config.primary_color;\n            }\n\n            this.mapStackPanel.addControl(mapBtn);\n\n            mapBtn.onPointerUpObservable.add(() => {\n                this._game.selectedMap = map;\n                this.room.send(ServerMsg.START_MAP_UPDATE, { key: map.key });\n                this.updateMaps();\n            });\n        }\n    }\n\n    create(guiMenu) {\n        let padding = 10;\n\n        // full width\n        const fullWidth = new Rectangle(\"fullwidth\");\n        fullWidth.width = 1;\n        fullWidth.height = 1;\n        fullWidth.thickness = 0;\n        fullWidth.background = \"#222222\";\n        fullWidth.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        fullWidth.fontFamily = this._game.config.fontFamily;\n        guiMenu.addControl(fullWidth);\n\n        // middle columm\n        const columnRect = new Rectangle(\"column\");\n        columnRect.width = \"400px\";\n        columnRect.height = 1;\n        columnRect.background = \"transparent\";\n        columnRect.thickness = 0;\n        columnRect.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        fullWidth.addControl(columnRect);\n\n        const subGrid = new Grid();\n\n        subGrid.addColumnDefinition(1);\n\n        subGrid.addRowDefinition(padding, true);\n\n        subGrid.addRowDefinition(50, true); // HEADER CANCEL BUTTON\n        subGrid.addRowDefinition(padding, true);\n\n        subGrid.addRowDefinition(50, true); // HEADER TITLE\n        subGrid.addRowDefinition(padding, true);\n\n        subGrid.addRowDefinition(120, true); // MAPS SECTION\n        subGrid.addRowDefinition(padding, true);\n\n        subGrid.addRowDefinition(1); // MAIN CONTENT TAKES REMAINING AVAILABLE SPACE\n        subGrid.addRowDefinition(padding, true);\n\n        subGrid.addRowDefinition(50, true); // CREATE BUTTON\n        subGrid.addRowDefinition(padding, true);\n\n        columnRect.addControl(subGrid);\n\n        // 1\n        const cancelButton = Button.CreateSimpleButton(\"cancelButton\", \"CANCEL\");\n        cancelButton.width = 1;\n        cancelButton.height = \"50px\";\n        cancelButton.color = \"white\";\n        cancelButton.fontSizeInPixels = 22;\n        cancelButton.thickness = 1;\n        cancelButton.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        cancelButton.verticalAlignment = Control.VERTICAL_ALIGNMENT_CENTER;\n        subGrid.addControl(cancelButton, 1);\n\n        cancelButton.onPointerUpObservable.add(() => {\n            this.room.leave();\n            this._game.setScene(SceneName.HOME);\n        });\n\n        // Hide cancel in PVP mode\n        if (this._game.isPvpMode) {\n            cancelButton.isVisible = false;\n        }\n\n        // 2 padding\n\n        // 3\n        const subHeaderGrid = new Rectangle();\n        subHeaderGrid.background = \"white\";\n        subHeaderGrid.thickness = 0;\n        subGrid.addControl(subHeaderGrid, 3);\n\n        const titleGame = new TextBlock(\"titleGame\" + this.room.roomId);\n        titleGame.width = 1;\n        titleGame.text = \"ROOM #\" + this.room.roomId;\n        titleGame.fontSizeInPixels = 26;\n        titleGame.color = this._game.config.primary_color;\n        titleGame.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        subHeaderGrid.addControl(titleGame);\n\n        // 4 padding\n\n        ///////////// MAPS\n        // 5\n        const mapBloc = new Rectangle();\n        mapBloc.background = \"white\";\n        mapBloc.thickness = 0;\n        subGrid.addControl(mapBloc, 5);\n\n        // add scrollable container\n        const mapScrollViewer = new ScrollViewer(\"mapScrollViewer\");\n        mapScrollViewer.width = 1;\n        mapScrollViewer.height = 1;\n        mapScrollViewer.thickness = 0;\n        mapScrollViewer.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        mapScrollViewer.verticalAlignment = Control.VERTICAL_ALIGNMENT_BOTTOM;\n        mapBloc.addControl(mapScrollViewer);\n\n        // add stack panel\n        const mapStackPanel = new StackPanel(\"mapStackPanel\");\n        mapStackPanel.width = \"100%\";\n        mapStackPanel.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        mapStackPanel.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        mapStackPanel.spacing = 5;\n        mapStackPanel.isVertical = false;\n        mapStackPanel.setPadding(padding, padding, padding, padding);\n        mapScrollViewer.addControl(mapStackPanel);\n        this.mapStackPanel = mapStackPanel;\n\n        this.updateMaps();\n\n        // 6 padding\n\n        ///////////// PLAYERS\n        // 7\n        const subMainGrid = new Rectangle();\n        subMainGrid.background = \"white\";\n        subMainGrid.thickness = 0;\n        subGrid.addControl(subMainGrid, 7);\n\n        // add scrollable container\n        const chatScrollViewer = new ScrollViewer(\"chatScrollViewer\");\n        chatScrollViewer.width = 1;\n        chatScrollViewer.height = 1;\n        chatScrollViewer.top = \"0px\";\n        chatScrollViewer.thickness = 0;\n        chatScrollViewer.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        chatScrollViewer.verticalAlignment = Control.VERTICAL_ALIGNMENT_BOTTOM;\n        subMainGrid.addControl(chatScrollViewer);\n\n        // add stack panel\n        const playerStackPanel = new StackPanel(\"playerStackPanel\");\n        playerStackPanel.width = \"100%\";\n        playerStackPanel.verticalAlignment = Control.VERTICAL_ALIGNMENT_TOP;\n        playerStackPanel.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_LEFT;\n        playerStackPanel.paddingTop = \"5px;\";\n        playerStackPanel.spacing = 5;\n        playerStackPanel.setPadding(padding, padding, padding, padding);\n        chatScrollViewer.addControl(playerStackPanel);\n        this.playerStackPanel = playerStackPanel;\n\n        // 8\n\n        // 9\n        const createBtn = Button.CreateSimpleButton(\"back\", \"START\");\n        createBtn.width = 1;\n        createBtn.thickness = 0;\n        createBtn.heightInPixels = this._game.config.button.height;\n        createBtn.color = this._game.config.button.color;\n        createBtn.background = this._game.config.button.background;\n        createBtn.textBlock.fontSizeInPixels = this._game.config.button.fontSize;\n        createBtn.horizontalAlignment = Control.HORIZONTAL_ALIGNMENT_CENTER;\n        createBtn.verticalAlignment = Control.VERTICAL_ALIGNMENT_CENTER;\n        subGrid.addControl(createBtn, 9);\n\n        ///////\n        createBtn.onPointerUpObservable.add(() => {\n            this.room.send(ServerMsg.START_GAME_REQUESTED);\n        });\n\n        // In PVP mode: hide map selection and START button\n        // Server auto-selects arena and auto-starts when all players join\n        if (this._game.isPvpMode) {\n            mapBloc.isVisible = false;\n            createBtn.isVisible = false;\n        }\n\n        // load scene\n        this._ui = guiMenu;\n    }\n\n    test() {\n        //////////// add map options\n        /*\n        var dropdownA = new MenuOptions(subHeaderGrid, { width: 180, height: 40 });\n        dropdownA.button.children[0].text = \"Ajouter\";\n        dropdownA.top = \"10px\";\n        dropdownA.left = \"10px\";\n        dropdownA.addOption(\"Option A\", function () {\n            alert(\"Option A\");\n        });\n        dropdownA.addOption(\"Option B\", function () {\n            alert(\"Option B\");\n        });\n        dropdownA.addOption(\"Option C\", function () {\n            alert(\"Option C\");\n        });\n        dropdownA.addOption(\"Option D\", function () {\n            alert(\"Option D\");\n        });*/\n    }\n}\n","import { uniqueNamesGenerator, animals, colors } from \"unique-names-generator\";\n\nconst isLocal = function () {\n    return window.location.host === \"localhost:8080\";\n};\n\nconst countPlayers = function (object) {\n    var length = 0;\n    for (var key in object) {\n        if (object.hasOwnProperty(key)) {\n            ++length;\n        }\n    }\n    return length;\n};\n\nconst randomNumberInRange = function (min, max) {\n    return Math.random() * (max - min) + min;\n};\n\nconst roundToTwo = function (num: number) {\n    return Math.round(num * 100) / 100;\n};\n\nconst roundTo = function (num: number, decimal: number = 2) {\n    if (num) {\n        let number = num.toFixed(decimal);\n        return parseFloat(number);\n    }\n    return 0;\n};\n\nconst bytesToSize = function (bytes) {\n    const sizes = [\"Bytes\", \"KB\", \"MB\", \"GB\", \"TB\"];\n    if (bytes === 0) return \"n/a\";\n    const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), sizes.length - 1);\n    if (i === 0) return `${bytes} ${sizes[i]}`;\n    return `${(bytes / 1024 ** i).toFixed(1)} ${sizes[i]}`;\n};\n\nconst distanceBetween = function (a, b): number {\n    return Math.sqrt(Math.pow(a.x - b.x, 2) + Math.pow(a.y - b.y, 2) + Math.pow(a.z - b.z, 2));\n};\n\nconst clamp = function (value: number, min: number, max: number): number {\n    return Math.min(Math.max(value, min), max);\n};\n\n/**\n * Generate a hexadecimal color from a number between 0-100\n * @param value number between 0 - 100\n * @returns\n */\nconst getHealthColorFromValue = function (value) {\n    let gHex = Math.round((value * 255) / 100); // rule of three to calibrate [0, 100] to [00, FF] (= [0, 255])\n    let rHex = 255 - gHex; // just the mirror of gHex\n    let gHexString = gHex.toString(16); // converting to traditional hex representation\n    let rHexString = rHex.toString(16);\n    gHexString = gHexString.length === 1 ? `0${gHex}` : gHexString; // compensating missing digit in case of single digit values\n    rHexString = rHexString.length === 1 ? `0${rHex}` : rHexString;\n    return `#${rHexString}${gHexString}00`; // composing both in a color code\n};\n\n/**\n * Generates a random username\n * @returns the username\n */\nconst generateUserName = function () {\n    return uniqueNamesGenerator({\n        dictionaries: [colors, animals],\n        separator: \" \",\n        style: \"capital\",\n    });\n};\n\nexport { generateUserName, isLocal, roundToTwo, roundTo, countPlayers, clamp, randomNumberInRange, distanceBetween, getHealthColorFromValue, bytesToSize };\n","if (process.env.NODE_ENV !== \"production\") {\n    import(\"@babylonjs/core/Debug/debugLayer\");\n    import(\"@babylonjs/inspector\");\n}\n\n// ES6 IMPORTS\n// if there are cases where es6 dependencies could be causing issues just try and load the whole babylon core, and\n// that fixes it, then it is a dependencies issue, check this link out for answers.\n// bjs post: https://forum.babylonjs.com/t/pickedmesh-is-null-in-onpointerobservable-after-update-to-6-25-0/45076/7\n// bjs docs: https://doc.babylonjs.com/setup/frameworkPackages/es6Support#faq\n// import(\"@babylonjs/core\");\n\nimport \"@babylonjs/core/Lights/Shadows/shadowGeneratorSceneComponent\";\nimport \"@babylonjs/core/Loading/loadingScreen\";\nimport \"@babylonjs/core/Animations/animatable\";\nimport \"@babylonjs/loaders/glTF/2.0/glTFLoader\";\nimport \"@babylonjs/loaders/glTF/2.0/Extensions/KHR_materials_pbrSpecularGlossiness\";\nimport \"@babylonjs/loaders/glTF/2.0/Extensions/KHR_draco_mesh_compression\";\nimport \"@babylonjs/core/Audio/audioSceneComponent\";\n/*\nimport \"@babylonjs/core/Culling/ray\";\nimport \"@babylonjs/core/Rendering/depthRendererSceneComponent\";\nimport \"@babylonjs/core/Rendering/outlineRenderer\";\n*/\n\nimport { Engine } from \"@babylonjs/core/Engines/engine\";\n\n// IMPORT SCREEN\nimport { SceneName } from \"../../shared/types\";\n\nimport { HomeScene } from \"./Scenes/HomeScene\";\nimport { Config } from \"../../shared/Config\";\nimport { GameController } from \"./Controllers/GameController\";\nimport { RoomScene } from \"./Scenes/RoomScene\";\nimport { GameScene } from \"./Scenes/GameScene\";\n\n// App class is our entire game application\nclass App {\n    // babylon\n    public canvas;\n    public engine: Engine;\n    public config: Config;\n    public game: GameController;\n\n    constructor() {\n        // create canvas\n        this.canvas = document.getElementById(\"renderCanvas\");\n\n        // set config\n        this.config = new Config();\n\n        // initialize babylon scene and engine\n        this._init();\n    }\n\n    private async _init(): Promise<void> {\n        // create engine\n        this.engine = new Engine(this.canvas, true, {\n            adaptToDeviceRatio: true,\n            antialias: true,\n        });\n\n        if (Engine.audioEngine) {\n            Engine.audioEngine.useCustomUnlockedButton = true;\n        }\n\n        window.addEventListener(\n            \"click\",\n            () => {\n                Engine.audioEngine.unlock();\n            },\n            { once: true }\n        );\n\n        // preload game data\n        this.game = new GameController(this);\n\n        // If PVP mode (has room URL param), GameController handles auto-join\n        // Otherwise show the home menu\n        if (!this.game.isPvpMode) {\n            this.game.setScene(SceneName.HOME);\n        }\n\n        // main render loop & state machine\n        await this._render();\n    }\n\n    private async _render(): Promise<void> {\n        // render loop\n        this.engine.runRenderLoop(async () => {\n            // monitor state\n            this.game.state = this.checkForSceneChange();\n\n            switch (this.game.state) {\n                ///////////////////////////////////////\n                // HOME SCENE\n                case SceneName.HOME:\n                    this.clearScene();\n                    this.game.currentScene = new HomeScene();\n                    await this.createScene();\n                    break;\n\n                ///////////////////////////////////////\n                // HOME SCENE\n                case SceneName.ROOM:\n                    this.clearScene();\n                    this.game.currentScene = new RoomScene();\n                    await this.createScene();\n                    break;\n\n                ///////////////////////////////////////\n                // GAME SCENE\n                case SceneName.GAME:\n                    this.clearScene();\n                    this.game.currentScene = new GameScene();\n                    await this.createScene();\n                    break;\n\n                default:\n                    break;\n            }\n\n            // render when scene is ready\n            this._process();\n        });\n\n        //for development: make inspector visible/invisible\n        //if (isLocal()) {\n        window.addEventListener(\"keydown\", (ev) => {\n            //Shift+Ctrl+Alt+I\n            if (ev.shiftKey && ev.ctrlKey && ev.altKey && ev.keyCode === 73) {\n                if (this.game.scene.debugLayer.isVisible()) {\n                    this.game.scene.debugLayer.hide();\n                } else {\n                    this.game.scene.debugLayer.show();\n                }\n            }\n        });\n        //}\n\n        //resize if the screen is resized/rotated\n        window.addEventListener(\"resize\", () => {\n            this.engine.resize();\n            if (this.game.currentScene && this.game.currentScene.resize) {\n                this.game.currentScene.resize();\n            }\n        });\n    }\n\n    private createScene() {\n        this.game.currentScene.createScene(this.game);\n        this.game.scene = this.game.currentScene._scene;\n        this.game.state = SceneName.NULL;\n    }\n\n    private checkForSceneChange() {\n        let currentScene = this.game.nextScene;\n        if (this.game.nextScene !== SceneName.NULL) {\n            this.game.nextScene = SceneName.NULL;\n            return currentScene;\n        }\n    }\n\n    private async _process(): Promise<void> {\n        // make sure scene and camera is initialized\n        if (this.game.scene && this.game.scene.activeCamera) {\n            // render scene\n            this.game.scene.render();\n        }\n    }\n\n    private clearScene() {\n        if (this.game.scene) {\n            this.game.engine.displayLoadingUI();\n            this.game.scene.detachControl();\n            this.game.scene.dispose();\n            this.game.currentScene = null;\n        }\n    }\n}\nnew App();\n","import { Schema, type } from \"@colyseus/schema\";\nimport { GameRoom } from \"../GameRoom\";\nimport { CellType } from \"../../../../shared/types\";\n\nexport class Cell extends Schema {\n    @type(\"string\") sessionId: string = \"\";\n    @type(\"string\") type: CellType;\n    @type(\"int8\") col: number = 0;\n    @type(\"int8\") row: number = 0;\n    @type(\"string\") playerId: string; // ID of the player occupying the cell (if any)\n    @type(\"string\") bombId: string; // ID of the bomb occupying the cell (if any)\n\n    public cellInfo;\n\n    constructor(args, room: GameRoom) {\n        super(args, room);\n\n        // add spawn data\n        Object.assign(this, args);\n\n        // get tile data\n        this.cellInfo = room.mapHelper.findTile(this.type, \"name\");\n    }\n}\n","class Config {\n    // general settings\n    title = \"BomberMan Mayhem\";\n    version = \"Version 0.0.1\";\n    lang = \"en\";\n\n    // server settings\n    port = 8406;\n    maxClients = 20; // set maximum clients per room\n    updateRate = 100; // Set frequency the patched state should be sent to all clients, in milliseconds\n    databaseUpdateRate = 10000; // the frequency at which server save players position\n\n    // players\n    speed = 1;\n\n    // theme\n    fontFamily = \"luckiest_guy\";\n    primary_color = \"purple\";\n    secondary_color = \"orange\";\n    button = {\n        background: \"purple\",\n        color: \"white\",\n        height: 50,\n        fontSize: 24,\n    };\n}\n\nexport { Config };\n","import tiles from \"./Data/tiles.json\";\nimport maps from \"./Data/maps.json\";\nimport { CellType, ITiles, Tile } from \"./types\";\nimport { Cell } from \"../server/src/Rooms/Entities/Cell\";\n\nexport class MapHelper {\n    public mapData;\n    public tiles: ITiles = {};\n\n    // spawn points\n    public spawnPoints: any = [];\n    public baseCells: any = [];\n    public cells: any = [];\n    public shadow_map: any = [];\n\n    constructor(mapName: string = \"map_01\") {\n        // get map data\n        this.mapData = maps[mapName].data;\n\n        // get all map tiles\n        this.tiles = tiles;\n\n        // generate level\n        this.generate(mapName);\n    }\n\n    /**\n     * Find a free spawn point for player\n     * @param sessionId\n     * @returns\n     */\n    public setSpawnPoint(sessionId) {\n        for (var i = 0; i < this.spawnPoints.length; i++) {\n            let spawn = this.spawnPoints[i];\n            if (!spawn.player) {\n                this.spawnPoints[i].player = sessionId;\n                return spawn;\n            }\n        }\n    }\n\n    /**\n     * Check if tile (row, col) is free\n     * @param row\n     * @param col\n     * @returns boolean\n     */\n    public isTileAvailable(col, row): boolean {\n        if (this.cells[col][row].isWalkable) {\n            return true;\n        }\n        return false;\n    }\n\n    /**\n     * check if cell is available.\n     * @param entities\n     * @param x\n     * @param z\n     * @returns\n     */\n    public isCellAvailable(cells, row, col) {\n        for (let [key, element] of cells) {\n            if (element.row === row && element.col === col && !element.cellInfo.isWalkable) {\n                console.log(\"CANNOT MOVE TO: \", element.type, row, col);\n                return false;\n            }\n        }\n        return true;\n    }\n\n    public async generate(map: string) {\n        this.mapData.forEach((col, colId) => {\n            col.forEach((tileID, rowId) => {\n                this.processTile(tileID, colId, rowId);\n            });\n        });\n        this.baseCells = [...this.cells];\n    }\n\n    public findTile(tileID, id = \"id\") {\n        let found;\n        for (let tID in tiles) {\n            let tile = tiles[tID];\n            if (tile && tile[id] === tileID) {\n                found = tile;\n            }\n        }\n        return found;\n    }\n\n    private processTile(tileID, colId, rowId) {\n        // get tile details\n        let foundTile = this.findTile(tileID) as Tile;\n\n        // tile not found\n        if (!foundTile) console.error(\"Tile: \" + tileID + \" does not exist, map data is corrupted\");\n\n        // spawnpoint tiles\n        if (foundTile.id == \"S\") {\n            this.spawnPoints.push({\n                player: false,\n                col: rowId,\n                row: colId,\n            });\n        }\n\n        // add to map cells\n        if (!this.cells[colId]) {\n            this.cells[colId] = [];\n        }\n        this.cells[colId][rowId] = foundTile;\n    }\n\n    //////////////////////////////////////////\n    //////////////////////////////////////////\n    //////// SERVER ONLY METHODS /////////////\n    //////////////////////////////////////////\n    //////////////////////////////////////////\n\n    public updateCell(colId, rowId, type) {}\n\n    public generateServerMap(room) {\n        this.mapData.forEach((row, rowId) => {\n            row.forEach((tileID, colId) => {\n                // get tile details\n                let foundTile = this.findTile(tileID) as Tile;\n\n                // tile not found\n                if (!foundTile) console.error(\"Tile: \" + tileID + \" does not exist, map data is corrupted\");\n\n                let sessionId = \"\" + rowId + \"-\" + colId;\n                let type = CellType.GROUND;\n\n                // if ground\n                let rand = Math.random();\n                if (tileID === \" \" && rand < 0.4) {\n                    type = CellType.BREAKABLE_WALL;\n                } else if (tileID === \" \" && rand < 0.5) {\n                    type = CellType.WALL;\n                }\n\n                // make sure no spawn point are at 2 tiles around\n                if (this.isNearSpawnPoint(rowId, colId)) {\n                    console.error(rowId, colId, \"IS NEAR A SPAWN POINT\");\n                    type = CellType.GROUND;\n                }\n\n                // if wall\n                if (tileID === \"W\") {\n                    type = CellType.WALL;\n                }\n\n                let wall = new Cell(\n                    {\n                        sessionId: sessionId,\n                        row: rowId,\n                        col: colId,\n                        type: type,\n                    },\n                    room\n                );\n\n                // add entity\n                room.state.cells.set(sessionId, wall);\n\n                // update shadowmap\n                if (!this.shadow_map[rowId]) {\n                    this.shadow_map[rowId] = [];\n                }\n                this.shadow_map[rowId][colId] = type;\n            });\n        });\n    }\n\n    public isNearSpawnPoint(rowId, colId, radius = 1) {\n        let found = false;\n        this.spawnPoints.forEach((spawn) => {\n            if (Math.abs(colId - spawn.col) <= radius && Math.abs(rowId - spawn.row) <= radius) {\n                found = true;\n            }\n        });\n        return found;\n    }\n\n    public findAvailableColor(players, colors) {\n        let randomColor = colors[Math.floor(Math.random() * colors.length)];\n        let found = false;\n        players.forEach((p) => {\n            if (randomColor === p.color) {\n                found = true;\n            }\n        });\n        if (found) {\n            return this.findAvailableColor(players, colors);\n        }\n        return randomColor;\n    }\n}\n","///////////////////////////////\n///////////////////////////////\n///////////////////////////////\n\ninterface ITileItem {\n    id: number;\n    animated: boolean;\n    sprite: string;\n    frames: number;\n    physics: boolean;\n    explosivable: boolean;\n    isPlayer: boolean;\n    isEnemy: boolean;\n}\n\nexport type Tile = {\n    id: string;\n    name: string;\n    width: number;\n    height: number;\n    isWalkable?: boolean;\n    offset_y?: number; // vertical offset\n};\n\nexport interface ITiles {\n    [key: string]: Tile;\n}\n\nexport enum CellType {\n    GROUND = \"ground\",\n    SPAWNPOINT = \"spawnpoint\",\n    WALL = \"wall\",\n    BREAKABLE_WALL = \"breakable_wall\",\n    EXPLOSION = \"explosion\",\n    PLAYER = \"player\",\n    BOMB = \"bomb\",\n    POWER_UP = \"power_up\",\n}\n\nexport enum PowerUpTypes {\n    HEALTH = 0,\n    BOMB,\n    SPEED,\n}\n\n///////////////////////////////\n///////////////////////////////\n///////////////////////////////\n\nexport enum SceneName {\n    NULL = 0,\n    HOME,\n    ROOM,\n    GAME,\n}\n\n///////////////////////////////\n///////////////////////////////\n///////////////////////////////\n\nexport type User = {\n    displayName: string;\n};\n\n///////////////////////////////\n///////////////////////////////\n///////////////////////////////\n\nexport enum ServerMsg {\n    PING = 1,\n    PONG,\n    START_GAME,\n    START_MAP_UPDATE,\n    START_GAME_REQUESTED,\n    PLAYER_MOVE,\n    PLACE_BOMB,\n    DO_EXPLOSION,\n    PLAYER_ELIMINATED,\n    GAME_OVER,\n}\n\nexport type PlayerInputs = {\n    seq: number;\n    h: number;\n    v: number;\n};\n\nexport enum ServerStatus {\n    CREATED = 1,\n    STARTED,\n    FINISHED,\n}\n","const a=a=>{a=1831565813+(a|=0)|0;let e=Math.imul(a^a>>>15,1|a);return e=e+Math.imul(e^e>>